class DeclarationError(ValueError):
    """A declaration outside the kit's vocabulary, naming what the author may choose from."""


def choices(what, value, allowed) -> NoReturn:
    raise DeclarationError(f"{what} '{value}' is not one of: {', '.join(allowed)}")


# ---- the glyph library: every kind, its style and its default size, read from assets/glyphs.xml --------------------


def library():
    """The kit's closed vocabulary from the glyph library: glyph kinds, edge kinds, the marker and the chips, each with its verbatim
    style, its legend phrase and its default size."""
    root = ET.parse(KIT / "assets" / "glyphs.xml").getroot()
    cells = {str(c.get("id")): c for c in root.iter("mxCell") if c.get("id")}

    def geometry(c):
        g = c.find("mxGeometry")
        return tuple(int(float(g.get(k, 0))) for k in ("width", "height")) if g is not None else (0, 0)

    glyphs, edges, marks = {}, {}, {}
    for cid, c in cells.items():
        if cid.startswith("g-") and not cid.endswith(("-text", "-tag", "-member", "-holder")):
            kind = cid[2:]
            glyphs[kind] = {"style": c.get("style"), "phrase": plain(c.get("value")), "size": geometry(c)}
        elif cid.startswith("e-") and c.get("edge") == "1":
            kind = cid[2:]
            edges[kind] = {"style": c.get("style"), "phrase": plain(cells[f"{cid}-text"].get("value"))}
        elif cid in ("m-marker", "m-rule", "m-count"):
            kind = cid[2:]
            marks[kind] = {"style": c.get("style"), "phrase": plain(cells[f"{cid}-text"].get("value")), "size": geometry(c)}
    glyphs["commit"]["phrase"] = "commit"
    glyphs.pop("commit-red", None)
    tag = cells["g-type-tag"]
    glyphs["type"]["tag"] = {"style": tag.get("style"), "size": geometry(tag)}
    # The action lens: an effect's where chip, and a call site's member row (one per command).
    tag = cells["g-effect-tag"]
    glyphs["effect"]["tag"] = {"style": tag.get("style"), "size": geometry(tag)}
    member = cells["g-callsite-a-member"]
    glyphs["callsite"]["member"] = {"style": member.get("style"), "size": geometry(member)}
    return {"glyphs": glyphs, "edges": edges, "marks": marks, "module": cells["g-module"].get("style")}


LIB = library()
GLYPH_KINDS = tuple(LIB["glyphs"])
EDGE_KINDS = tuple(LIB["edges"])


def span_vocabulary():
    """Every span label the kit allows, flattened from the vocabularies block of drawio.yml and the tracks of variants.yml, with the list
    each came from."""
    words = {}
    for name, entries in DEFAULTS["vocabularies"].items():
        for word in str(entries).split(","):
            word = word.strip()
            if word:
                words.setdefault(word, name)
    for track in minimaps.tracks():
        words.setdefault(track, "tracks")
    return words


# ---- the declaration: read, validate, normalise -------------------------------------------------------------------


def diagram_of(path):
    """A diagram's stem, `<page-folder>/.assets/<name>`, from the stem itself or either file of its pair."""
    path = Path(path)
    for suffix in (SOURCE, SLIDE):
        if path.name.endswith(suffix):
            return path.with_name(path.name[: -len(suffix)])
    return path


def source_of(diagram):
    """The diagram's one source, `<name>.drawio.yml`."""
    stem = diagram_of(diagram)
    return stem.with_name(stem.name + SOURCE)


def slide_of(diagram):
    """The diagram's drawing, `<name>.drawio.png`, put from its source."""
    stem = diagram_of(diagram)
    return stem.with_name(stem.name + SLIDE)


CARRIERS = ("file", "article")  # where a declaration lives: <name>.drawio.yml beside the png, or a `yml drawio` block in its article
FENCE = "yml drawio"  # the info string of an article's declaration block, the way a mermaid block is fenced


def carrier_of(diagram):
    """A diagram's carrier: its entry under drawio.yml carriers:, keyed by its stem's repository path, else renderer.carrier."""
    path = carrier_key(diagram)
    carrier = DEFAULTS.get("carriers", {}).get(path, DEFAULTS["renderer"]["carrier"])
    if carrier not in CARRIERS:
        raise DeclarationError(f"drawio.yml gives {path} the carrier '{carrier}', not one of {', '.join(CARRIERS)}")
    return carrier


def blocks_in(text, name):
    """The `yml drawio` blocks of a page that sit directly above an image embedding `.assets/<name>.drawio.png`, only blank lines
    between, each as the (start, end) of its body in the text."""
    pattern = re.compile(
        r"^```"
        + re.escape(FENCE)
        + r"[ \t]*\n((?:(?!```).*\n)*)```[ \t]*\n(?:[ \t]*\n)*!\[[^\]]*\]\((?:\./)?\.assets/"
        + re.escape(name)
        + r"\.drawio\.png\)",
        re.M,
    )
    return [(m.start(1), m.end(1)) for m in pattern.finditer(text)]


def articles(diagram):
    """The pages that may carry a diagram's declaration: the Markdown beside its `.assets`, never a slide, whose body the deck shows."""
    stem = diagram_of(diagram)
    return [page for page in sorted(stem.parent.parent.glob("*.md")) if not page.name.endswith(".slide.md")]


def article_block(diagram):
    """The one block in the diagram's article that declares it: (page, start, end). The articles are the pages beside its `.assets`; no
    block, or a block in two places, fails naming the pages."""
    stem = diagram_of(diagram)
    found = [(page, *span) for page in articles(stem) for span in blocks_in(page.read_text(encoding="utf-8"), stem.name)]
    if len(found) != 1:
        pages = ", ".join(sorted({p.name for p, _, _ in found})) or "none"
        raise DeclarationError(
            f"{stem}: the article carrier needs exactly one `{FENCE}` block above its image, found {len(found)} ({pages})"
        )
    return found[0]


def declared(diagram):
    """Whether the diagram has its declaration in its carrier."""
    if carrier_of(diagram) == "file":
        return source_of(diagram).is_file()
    try:
        article_block(diagram)
        return True
    except DeclarationError:
        return False


def read_source(diagram):
    """The declaration's text from its carrier, and where it lives (the file, or the article page)."""
    if carrier_of(diagram) == "file":
        source = source_of(diagram)
        if not source.is_file():
            raise DeclarationError(f"{diagram}: no {source.name}, the diagram's one source")
        return source.read_text(encoding="utf-8"), source
    page, start, end = article_block(diagram)
    return page.read_text(encoding="utf-8")[start:end], page


def write_source(diagram, text):
    """Write the declaration's text into its carrier: the file whole, or the article's block in place, the rest of the page as it was."""
    if carrier_of(diagram) == "file":
        source_of(diagram).write_text(text, encoding="utf-8", newline="\n")  # LF on every platform, as the formatter keeps it
        return source_of(diagram)
    page, start, end = article_block(diagram)
    whole = page.read_text(encoding="utf-8")
    page.write_text(whole[:start] + text.rstrip("\n") + "\n" + whole[end:], encoding="utf-8", newline="\n")
    return page


def carrier_findings(diagram):
    """A diagram declared in both carriers: the file beside its png and a block in its article. Empty when it has one."""
    stem = diagram_of(diagram)
    blocks = [p.name for p in articles(stem) if blocks_in(p.read_text(encoding="utf-8"), stem.name)]
    if source_of(stem).is_file() and blocks:
        return [f"declared in both carriers: {source_of(stem).name} and a `{FENCE}` block in {', '.join(blocks)}"]
    return []


CONFIG = KIT / "configs" / "drawio.yml"  # where carry records a diagram's carrier, under carriers:


def carrier_key(diagram):
    """The key a diagram's carrier is recorded under in drawio.yml carriers:, the same carrier_of reads."""
    stem = diagram_of(diagram).resolve()
    repo = KIT.parents[1]
    return stem.relative_to(repo).as_posix() if stem.is_relative_to(repo) else stem.name


def image_in(page, name):
    """The spans of the images in a page's text that embed `.assets/<name>.drawio.png`."""
    pattern = re.compile(r"^!\[[^\]]*\]\((?:\./)?\.assets/" + re.escape(name) + r"\.drawio\.png\)", re.M)
    return [m.start() for m in pattern.finditer(page.read_text(encoding="utf-8"))]


def recorded_carriers(text, key, carrier):
    """drawio.yml's text with the key's carriers: entry set to the carrier, or dropped when the carrier is the default, edited line by
    line so every comment and every other entry stays as written."""
    lines = text.split("\n")
    head = next((i for i, line in enumerate(lines) if re.match(r"^carriers:", line)), None)
    if head is None:
        raise DeclarationError(f"{CONFIG}: no top-level carriers: to record {key} under")
    end = next((i for i in range(head + 1, len(lines)) if lines[i] and not lines[i].startswith((" ", "#"))), len(lines))
    entry = re.compile(r"^  " + re.escape(key) + r":")
    kept = [line for line in lines[head + 1 : end] if not entry.match(line)]
    if carrier != DEFAULTS["renderer"]["carrier"]:
        last = max((i for i, line in enumerate(kept) if line.startswith("  ") and line.strip()), default=-1)
        kept.insert(last + 1, f"  {key}: {carrier}")
    # An empty carriers: stays a mapping, `{}`, so a reader never meets a null; a first entry opens it again.
    opener = re.sub(r"^carriers:[ \t]*\{\}", "carriers:", lines[head])
    if not any(line.startswith("  ") and line.strip() for line in kept):
        opener = re.sub(r"^carriers:", "carriers: {}", opener)
    return "\n".join(lines[:head] + [opener] + kept + lines[end:])


def rekeyed(text, old, new):
    """drawio.yml's text with every carriers: and roles: entry keyed by the stem `old`, or by a stem under the folder `old`, keyed by `new`
    instead, edited line by line so every comment and every other entry stays as written; the one editor a diagram move uses."""
    lines = text.split("\n")
    entry = re.compile(r"^(  )(" + re.escape(old) + r")(?=:|/)")
    section = None
    for i, line in enumerate(lines):
        if line and not line.startswith((" ", "#")):
            section = re.match(r"^([a-z_]+):", line)
            section = section.group(1) if section else None
        elif section in ("carriers", "roles"):
            lines[i] = entry.sub(lambda m: m.group(1) + new, line, count=1)
    return "\n".join(lines)


IGNORE_LINE = re.compile(r"^[ \t]*#[ \t]*cspell:ignore[ \t]+(.*?)[ \t]*$", re.M)  # a yml's cspell ignore comment
PAGE_IGNORE = re.compile(r"^<!-- cspell:ignore[ \t]+(.*?)[ \t]*-->[ \t]*$", re.M)  # a page's own cspell ignore comment


def with_page_ignores(whole, words):
    """A page's text with the words added to its own `<!-- cspell:ignore … -->` comment, made under the title when it has none, so a
    word a declaration told cspell to ignore stays ignored once the declaration is a block of the page."""
    if not words:
        return whole
    found = PAGE_IGNORE.search(whole)
    if found:
        held = found.group(1).split()
        merged = held + [w for w in words if w not in held]
        return whole[: found.start()] + f"<!-- cspell:ignore {' '.join(merged)} -->" + whole[found.end() :]
    lines = whole.split("\n")
    title = next((i for i, line in enumerate(lines) if line.startswith("# ")), -1)
    return "\n".join(
        lines[: title + 1]
        + ([""] if title >= 0 else [])
        + [f"<!-- cspell:ignore {' '.join(words)} -->"]
        + ([] if title >= 0 else [""])
        + lines[title + 1 :]
    )


def without_page_ignores(whole, body):
    """The page's ignore words the block body uses, and the page's text with each word the rest of the page no longer uses dropped from
    its comment; a comment left empty goes with the blank line after it."""
    found = PAGE_IGNORE.search(whole)
    if not found:
        return [], whole
    uses = lambda text, w: re.search(r"(?<![A-Za-z])" + re.escape(w) + r"(?![A-Za-z])", text, re.I) is not None
    held = found.group(1).split()
    rest = whole[: found.start()] + whole[found.end() :]
    taken = [w for w in held if uses(body, w)]
    kept = [w for w in held if w not in taken or uses(rest, w)]
    if kept:
        return taken, whole[: found.start()] + f"<!-- cspell:ignore {' '.join(kept)} -->" + whole[found.end() :]
    return taken, whole[: found.start()] + re.sub(r"^\n\n?", "", whole[found.end() :])


def carry(diagram, carrier):
    """Move a diagram's declaration to the other carrier: the yml beside its png becomes a `yml drawio` block directly above the image in
    its one article, or the block becomes the yml, and drawio.yml carriers: records it. The move is all or nothing: it refuses a diagram
    already in that carrier, declared twice or not at all, and restores every file when the declaration it reads back differs."""
    stem = diagram_of(diagram)
    if carrier not in CARRIERS:
        raise DeclarationError(f"{stem}: carry takes {' or '.join(CARRIERS)}, not '{carrier}'")
    if carrier_of(stem) == carrier:
        raise DeclarationError(f"{stem}: already in the {carrier} carrier")
    twice = carrier_findings(stem)
    if twice:
        raise DeclarationError(f"{stem}: {'; '.join(twice)}")
    text, where = read_source(stem)
    before = normalise(yaml.safe_load(text) or {}, where=str(where))
    # A file's comment head is the file's own, never part of the declaration, so the block takes the body alone.
    lines = text.split("\n")
    body = "\n".join(lines[next((i for i, line in enumerate(lines) if line.strip() and not line.startswith("#")), len(lines)) :])
    # The words a yml tells cspell to ignore move to the page's own comment; a comment inside a code block would not be read.
    words = [w for found in IGNORE_LINE.findall(text) for w in found.split()]
    body = IGNORE_LINE.sub("", body).strip("\n") + "\n"
    config = CONFIG.read_text(encoding="utf-8")
    saved = {CONFIG: config}
    if carrier == "article":
        pages = [(page, at) for page in articles(stem) for at in image_in(page, stem.name)]
        if len(pages) != 1:
            names = ", ".join(sorted({p.name for p, _ in pages})) or "none"
            raise DeclarationError(
                f"{stem}: the article carrier needs exactly one article image of {stem.name}.drawio.png beside .assets, found {len(pages)} ({names})"
            )
        page, at = pages[0]
        whole = page.read_text(encoding="utf-8")
        saved[page] = whole
        saved[source_of(stem)] = text
        changes = [(page, with_page_ignores(whole[:at] + f"```{FENCE}\n{body}```\n\n" + whole[at:], words)), (source_of(stem), None)]
    else:
        page, start, end = article_block(stem)
        whole = page.read_text(encoding="utf-8")
        saved[page] = whole
        saved[source_of(stem)] = None
        # The block runs from its fence line to the blank lines that end at the image, which stays where it was.
        opening = whole.rfind(f"```{FENCE}", 0, start)
        after = re.match(r"```[ \t]*\n(?:[ \t]*\n)*", whole[end:])
        taken, rest = without_page_ignores(whole[:opening] + whole[end + after.end() :], body)
        changes = [(source_of(stem), (f"# cspell:ignore {' '.join(taken)}\n\n" if taken else "") + body), (page, rest)]
    changes.append((CONFIG, recorded_carriers(config, carrier_key(stem), carrier)))
    held = DEFAULTS.get("carriers")
    try:
        for path, new in changes:
            if new is None:
                path.unlink()
            else:
                path.write_text(new, encoding="utf-8", newline="\n")
        DEFAULTS["carriers"] = (yaml.safe_load(changes[-1][1]) or {}).get("carriers") or {}
        after_text, after_where = read_source(stem)
        if carrier_findings(stem) or normalise(yaml.safe_load(after_text) or {}, where=str(after_where)) != before:
            raise DeclarationError(f"{stem}: the declaration read back from the {carrier} carrier differs, so nothing was moved")
    except Exception:
        for path, old in saved.items():
            if old is None:
                path.unlink(missing_ok=True)
            else:
                path.write_text(old, encoding="utf-8", newline="\n")
        DEFAULTS["carriers"] = held
        raise
    # The png is what Build-Diagrams takes for a diagram whose declaration sits in an article: the stem alone names no file.
    return read_source(stem)[1], stem.with_name(stem.name + SLIDE)


def load(folder):
    """The declaration of a diagram, from its carrier."""
    text, where = read_source(folder)
    return normalise(yaml.safe_load(text) or {}, where=str(where))


def save(folder, declaration):
    """Write a declaration into the diagram's carrier. The drawing carries no description, so a declaration read back by get keeps the
    description the source already has."""
    if declared(folder):
        text, where = read_source(folder)
        held = normalise(yaml.safe_load(text) or {}, where=str(where))
        if not declaration.get("description"):
            declaration = {**declaration, "description": held["description"]}
        # The drawing carries the ADR codes of `about:` in its subtitle; a drawing without them keeps the source's.
        about = {
            "lens": declaration["about"]["lens"],
            **{key: declaration["about"][key] or held["about"][key] for key in minimaps.ABOUT_KEYS},
        }
        proves = declaration["about"].get("proves") or held["about"].get("proves")  # the drawing never carries the proof file
        if proves:
            about["proves"] = proves
        declaration = {**declaration, "about": about, "content": undrawn(declaration["content"], held)}
        # The drawing carries a row only as its expansion: when the drawing still draws what the source's rows expand to, the source
        # keeps its rows (the layout is the drawing's); when it draws something else, the drawing wins.
        generated = held["content"].get("generated") or set()
        if generated:
            old, new = drawn(held["content"]), drawn(declaration["content"])
            mine = lambda d: (
                {k: d[key].get(k) for key in ("groups", "glyphs") for k in generated if k in d[key]},
                [e for e in d["edges"] if dict(e)["from"] in generated and dict(e)["to"] in generated],
            )
            if mine(old) == mine(new):
                kept = {k: held["content"][k] for k in SHORTHAND + ("generated",) if k in held["content"]}
                declaration = {**declaration, "content": {**declaration["content"], **kept}}
    write_source(folder, dump(declaration))


TOP_KEYS = ("description", "about", "content", "layout")
# Content the drawing cannot carry exactly: the kind is never drawn, a layout can place the bands against the flow, and the legend
# prints the relation without its parenthesis or not at all. get guesses each for a drawing without a source; a source keeps its own.
SOURCE_ONLY = ("kind", "flow", "relation", "thick")


def shown_minimaps(entries):
    """The ids of the shown minimaps, in order: each entry of content.minimaps is an id or { id: { exclude: [...] } }."""
    return [next(iter(entry)) if isinstance(entry, dict) else entry for entry in entries or []]


def undrawn(content, declared):
    """A content read back by get, with what the declared source says and its drawing does not show laid over it: the SOURCE_ONLY
    facts, the band order when the layout places every band, and the band of an item the layout places, which get can only guess
    from where it sits (put refuses a place inside another band)."""
    source, layout = declared["content"], declared["layout"]
    out = {**content, **{k: source[k] for k in SOURCE_ONLY}}
    # An action diagram's where and a used legend are read from the chips and the legend only as far as the drawing tells; the source
    # keeps its own words for both.
    for key in ("where", "legend"):
        if key in source and source["lens"] == ACTION_LENS:
            out[key] = source[key]
    if source["lens"] == ACTION_LENS:  # what a note's show: hid, its words or its call or observation, stays the source's
        hidden = {e["id"]: {k: v for k, v in e.items() if k in ("says", "proves", "call")} for e in source["effects"]}
        merged = [{**hidden.get(e["id"], {}), **e} for e in out.get("effects", [])]
        out["effects"] = [{k: e[k] for k in EFFECT_KEYS if k in e} for e in merged]
    # The drawing shows which minimaps but not what their author excludes: the source's entries stay while it shows the same three.
    if not content.get("minimaps") or shown_minimaps(content["minimaps"]) == shown_minimaps(source["minimaps"]):
        out["minimaps"] = source["minimaps"]
    if (
        source["bands"]
        and all(b["id"] in layout for b in source["bands"])
        and {b["id"] for b in source["bands"]} == {b["id"] for b in content["bands"]}
    ):
        out["bands"] = source["bands"]
    bands = {b["id"] for b in source["bands"]}
    held = {i["id"]: i["in"] for key in ("groups", "glyphs") for i in source.get(key) or [] if i["id"] in layout and i["in"] in bands}
    for key in ("groups", "glyphs"):
        out[key] = [{**i, "in": held[i["id"]]} if i["id"] in held and i.get("in") in bands else i for i in out.get(key) or []]
    return out


ABOUT_KEYS = ("adrs", "lens", "proves")  # the subject's ADR codes, the lens it is drawn through, and an action diagram's proof file
# The subject's former lists: read and ignored, never written back, so a get or a save drops them (the minimaps' rework).
RETIRED_ABOUT_KEYS = ("tracks", "languages", "modules", "files")


def drawn(content):
    """What a content draws, the same whether it was written with rows or read back from the drawing: its cells keyed by id, its
    edges as a set, and the rest as written."""
    out = {k: v for k, v in content.items() if k not in SHORTHAND + ("generated",)}
    for key in ("groups", "glyphs", "notes"):
        out[key] = {i["id"]: i for i in content.get(key) or []}
    out["edges"] = sorted(tuple(sorted(e.items())) for e in content.get("edges") or [])
    return out


def expand_lanes(content, where):
    """The content with each lane's commits written out: a commit glyph in the lane's band per commit, and an edge from a commit's
    `from` to it, a branch leaving or rejoining the trunk. Returns the written-out ids, so dump writes the lane back."""
    lanes = content.get("lanes") or []
    if not lanes:
        return content, set()
    bands = {b["id"] for b in content.get("bands") or [] if isinstance(b, dict)}
    glyphs, edges = list(content.get("glyphs") or []), list(content.get("edges") or [])
    generated = set()
    for raw_lane in lanes:
        if not isinstance(raw_lane, dict):
            raise DeclarationError(f"{where}: a lane is a map of band, steps, and optionally trunk, commits and marks")
        for key in raw_lane:
            if key not in LANE_KEYS:
                choices(f"{where}: lane key", key, LANE_KEYS)
        band, steps = str(raw_lane.get("band", "")), raw_lane.get("steps")
        if band not in bands:
            choices(f"{where}: lane band", band, tuple(sorted(bands)))
        if not isinstance(steps, int) or steps < 2:
            raise DeclarationError(f"{where}: lane '{band}' steps is a whole number of at least 2")
        for raw in raw_lane.get("commits") or []:
            commit = entry(raw, ("id", "step", "label"), where, "lane commit", optional={"row": 0, "state": COMMIT_STATES[0], "from": ""})
            if not commit["step"].isdigit() or not 1 <= int(commit["step"]) <= steps:
                raise DeclarationError(f"{where}: lane commit '{commit['id']}' step {commit['step']} is not one of 1 to {steps}")
            if commit["row"] not in ("-1", "0", "1"):
                choices(f"{where}: lane commit '{commit['id']}' row", commit["row"], ("-1", "0", "1"))
            glyphs.append(
                {
                    "id": commit["id"],
                    "kind": "commit",
                    "label": commit["label"],
                    "in": band,
                    **({"state": commit["state"]} if commit["state"] != COMMIT_STATES[0] else {}),
                }
            )
            if commit["from"]:
                edges.append({"from": commit["from"], "to": commit["id"], "kind": "flow"})
            generated.add(commit["id"])
        # Any other glyph a lane holds sits at a step too: a gate, an environment slot and the commits occupying it, a code unit.
        for raw in raw_lane.get("glyphs") or []:
            item = entry(raw, ("id", "step", "kind", "label"), where, "lane glyph", optional={"row": 0})
            if not item["step"].isdigit() or not 1 <= int(item["step"]) <= steps:
                raise DeclarationError(f"{where}: lane glyph '{item['id']}' step {item['step']} is not one of 1 to {steps}")
            if item["row"] not in ("-1", "0", "1"):
                choices(f"{where}: lane glyph '{item['id']}' row", item["row"], ("-1", "0", "1"))
            glyphs.append({"id": item["id"], "kind": item["kind"], "label": item["label"], "in": band})
            generated.add(item["id"])
        mine = {str(c["id"]) for c in raw_lane.get("commits") or [] if isinstance(c, dict)}
        for raw in raw_lane.get("marks") or []:
            mark = entry(raw, ("at", "text"), where, "lane mark")
            if mark["at"] not in mine:
                choices(f"{where}: lane mark at", mark["at"], tuple(sorted(mine)))
    return {**content, "glyphs": glyphs, "edges": edges}, generated


def expand_rows(content, where):
    """The content with each row of a lane template written out: a frame named by the row, a commit dot per step in the state
    the template gives the step (the row's start state first), an edge between neighbours labelled with the step, and a drop from
    every dot to a dot in the template's drop state. The written-out cells carry ids from the row's id; returns them as well, so
    dump writes the row back, never its expansion."""
    templates, rows = content.get("templates") or {}, content.get("rows") or []
    if not rows:
        return content, set()
    if not isinstance(templates, dict) or not isinstance(rows, list):
        raise DeclarationError(f"{where}: templates is a map of name: {{ states, drop }}, and rows a list of rows")
    groups, glyphs, edges = list(content.get("groups") or []), list(content.get("glyphs") or []), list(content.get("edges") or [])
    generated = set()
    for raw_row in rows:
        skip = raw_row.get("skip") or [] if isinstance(raw_row, dict) else []
        row = entry(
            {k: v for k, v in raw_row.items() if k != "skip"} if isinstance(raw_row, dict) else raw_row,
            ("id", "template", "label", "in", "start", "steps"),
            where,
            "row",
        )
        if row["template"] not in templates:
            choices(f"{where}: row '{row['id']}' template", row["template"], tuple(templates))
        template = templates[row["template"]]
        if not isinstance(template, dict) or not isinstance(template.get("states"), dict) or not template.get("drop"):
            raise DeclarationError(f"{where}: template '{row['template']}' is a map of states (step: state) and drop (a state)")
        for key in template:
            if key not in ("states", "drop"):
                choices(f"{where}: template '{row['template']}' key", key, ("states", "drop"))
        states = {str(step): str(state) for step, state in template["states"].items()}
        for state in [*states.values(), str(template["drop"]), row["start"]]:
            if state not in COMMIT_STATES:
                choices(f"{where}: template '{row['template']}' state", state, COMMIT_STATES)
        template = {"states": states, "drop": str(template["drop"])}
        for step in row["steps"]:
            if step not in states:
                choices(f"{where}: row '{row['id']}' step", step, tuple(states))
        trail = [row["start"]] + [states[step] for step in row["steps"]]
        groups.append({"id": row["id"], "label": row["label"], "in": row["in"]})
        for n, state in enumerate(trail):
            dot, drop = f"{row['id']}-{n}", f"{row['id']}-{n}-drop"
            glyphs.append(
                {"id": dot, "kind": "commit", "label": "x", "in": row["id"], **({"state": state} if state != COMMIT_STATES[0] else {})}
            )
            glyphs.append(
                {
                    "id": drop,
                    "kind": "commit",
                    "label": "x",
                    "in": row["id"],
                    **({"state": template["drop"]} if template["drop"] != COMMIT_STATES[0] else {}),
                }
            )
            edges.append({"from": dot, "to": drop, "kind": "fail"})
            if n:
                edges.append({"from": f"{row['id']}-{n - 1}", "to": dot, "kind": "flow", "label": row["steps"][n - 1]})
            generated |= {dot, drop}
        # A skipped step: the commit may leave the state before it straight for the state after the next step, a bypass under
        # the dot the step would reach.
        for step in skip if isinstance(skip, list) else [skip]:
            if str(step) not in row["steps"][:-1]:
                choices(f"{where}: row '{row['id']}' skip", str(step), tuple(row["steps"][:-1]))
            n = row["steps"].index(str(step))
            edges.append({"from": f"{row['id']}-{n}", "to": f"{row['id']}-{n + 2}", "kind": "bypass"})
        generated.add(row["id"])
    return {**content, "groups": groups, "glyphs": glyphs, "edges": edges}, generated


def normalise(raw, where="the declaration"):
    """The declaration with every default filled, every vocabulary checked, and every list in its canonical shape."""
    if not isinstance(raw, dict) or "content" not in raw:
        raise DeclarationError(f"{where}: a declaration is a map with a description:, a content: section and an optional layout: section")
    for key in raw:
        if key not in TOP_KEYS:
            choices(f"{where}: top-level key", key, TOP_KEYS)
    content = dict(raw["content"] or {})
    for key in content:
        if key not in CONTENT_KEYS:
            choices(f"{where}: content key", key, CONTENT_KEYS)
    content, generated = expand_rows(content, where)
    content, lane_generated = expand_lanes(content, where)
    generated |= lane_generated
    out: dict = {"title": str(content.get("title", "")).strip()}
    # Only a declaration written with rows, lanes or rules carries them, and the ids their expansion wrote.
    for key in SHORTHAND:
        if content.get(key):
            out[key] = content[key]
    if generated or content.get("rules"):
        out["generated"] = generated
    if not out["title"]:
        raise DeclarationError(f"{where}: content.title is the finding the reader leaves with; it is empty")
    about_raw = raw.get("about") or {}
    if not isinstance(about_raw, dict):
        raise DeclarationError(f"{where}: about is a map of {', '.join(ABOUT_KEYS)}")
    for key in about_raw:
        if key not in ABOUT_KEYS and key not in RETIRED_ABOUT_KEYS:
            choices(f"{where}: about key", key, ABOUT_KEYS)
    lens = about_raw.get("lens", "meta")
    if lens not in DEFAULTS["lenses"]:
        choices(f"{where}: about.lens", lens, tuple(DEFAULTS["lenses"]))
    out["lens"] = lens
    kind = content.get("kind", KINDS[0])
    if kind not in KINDS:
        choices(f"{where}: kind", kind, KINDS)
    out["kind"] = kind
    flow = content.get("flow", FLOWS[0])
    if flow not in FLOWS:
        choices(f"{where}: flow", flow, FLOWS)
    out["flow"] = flow
    themes = tuple(DEFAULTS["themes"])
    theme = content.get("theme", themes[0])
    if theme not in themes:
        choices(f"{where}: theme", theme, themes)
    out["theme"] = theme
    # The action lens draws its cause, its action and its effects, and the renderer draws every edge; the proof lens draws the action's
    # statement alone; every other lens draws bands.
    if lens in (ACTION_LENS, PROOF_LENS):
        for key in ("bands", "groups", "glyphs", "notes", "edges", "spans", "markers", "chips", "relation", "thick") + SHORTHAND:
            if content.get(key):
                raise DeclarationError(
                    f"{where}: content.{key} is the band grammar; the {lens} lens draws an action, and the renderer draws the rest"
                )
        if lens == PROOF_LENS:
            for key in ("cause", "effects", "proof"):
                if key in content:
                    raise DeclarationError(f"{where}: content.{key} belongs to the action lens; the proof lens draws the action's statement alone")
    else:
        for key in ACTION_KEYS + ("proof",):
            if key in content:
                raise DeclarationError(f"{where}: content.{key} belongs to the action lens; this diagram's lens is {lens}")
    out["bands"] = [entry(b, ("id", "label"), where, "band") for b in content.get("bands") or []]
    ids = {}
    for b in out["bands"]:
        ids.setdefault(b["id"], "band")
    out["groups"] = [entry(g, ("id", "label", "in"), where, "group") for g in content.get("groups") or []]
    for g in out["groups"]:
        if g["id"] in ids:
            raise DeclarationError(f"{where}: id '{g['id']}' is used twice")
        ids[g["id"]] = "group"
    out["glyphs"] = []
    for raw_glyph in content.get("glyphs") or []:
        # A commit carries its state in the locked palette (bvt by default), may be a ghost (faded and dashed), and is a dot unless
        # its shape is box: a state drawn as a named box in its palette colour.
        extra = {k: raw_glyph[k] for k in ("state", "ghost", "shape") if isinstance(raw_glyph, dict) and k in raw_glyph}
        g = entry(
            {k: v for k, v in raw_glyph.items() if k not in extra} if isinstance(raw_glyph, dict) else raw_glyph,
            ("id", "kind", "label", "in"),
            where,
            "glyph",
        )
        if extra and g["kind"] != "commit":
            raise DeclarationError(f"{where}: glyph '{g['id']}' is a {g['kind']}; only a commit takes a state, ghost or shape")
        if extra.get("shape", COMMIT_SHAPES[0]) not in COMMIT_SHAPES:
            choices(f"{where}: commit '{g['id']}' shape", extra["shape"], COMMIT_SHAPES)
        if extra.get("shape", COMMIT_SHAPES[0]) != COMMIT_SHAPES[0]:
            g["shape"] = str(extra["shape"])
        if extra.get("state", COMMIT_STATES[0]) not in COMMIT_STATES:
            choices(f"{where}: commit '{g['id']}' state", extra["state"], COMMIT_STATES)
        if extra.get("state", COMMIT_STATES[0]) != COMMIT_STATES[0]:
            g["state"] = str(extra["state"])
        if extra.get("ghost") is True:
            g["ghost"] = True
        out["glyphs"].append(g)
    for g in out["glyphs"]:
        if g["kind"] not in GLYPH_KINDS:
            choices(f"{where}: glyph '{g['id']}' kind", g["kind"], GLYPH_KINDS)
        if g["id"] in ids:
            raise DeclarationError(f"{where}: id '{g['id']}' is used twice")
        ids[g["id"]] = "glyph"
    for item in out["groups"] + out["glyphs"]:
        # A glyph sits in a band or a group; a commit may also sit in an environment, as its occupant.
        envs = [g["id"] for g in out["glyphs"] if g["kind"] == "env"]
        occupant = item.get("kind") == "commit" and item["in"] in envs
        if item["in"] not in ids or (ids[item["in"]] == "glyph" and not occupant):
            holders = [i for i, k in ids.items() if k != "glyph"] + (envs if item.get("kind") == "commit" else [])
            choices(f"{where}: '{item['id']}' in", item["in"], holders)
    # A note is a free text block in a band or a group, placed like a glyph; its lines are its text's lines.
    out["notes"] = []
    for raw_note in content.get("notes") or []:
        note = entry(raw_note, ("id", "in", "text"), where, "note")
        if note["id"] in ids:
            raise DeclarationError(f"{where}: id '{note['id']}' is used twice")
        if ids.get(note["in"]) not in ("band", "group"):
            choices(f"{where}: note '{note['id']}' in", note["in"], [i for i, k in ids.items() if k in ("band", "group")])
        ids[note["id"]] = "note"
        out["notes"].append(note)
    # A gate rule stands between two steps of the first lane, across every lane: after step n, manual or automated.
    lanes = content.get("lanes") or []
    for raw_rule in content.get("rules") or []:
        rule = entry(raw_rule, ("after", "kind"), where, "rule")
        if not lanes:
            raise DeclarationError(f"{where}: a rule stands between steps of a lane; the diagram declares no lanes")
        if rule["kind"] not in RULE_KINDS:
            choices(f"{where}: rule kind", rule["kind"], RULE_KINDS)
        if not rule["after"].isdigit() or not 1 <= int(rule["after"]) < int(lanes[0]["steps"]):
            raise DeclarationError(f"{where}: rule after {rule['after']} is not a step of 1 to {int(lanes[0]['steps']) - 1}")
    vocabulary = span_vocabulary()
    out["spans"] = []
    for s in content.get("spans") or []:
        span = entry(s, ("id", "label", "over"), where, "span")
        if span["label"] not in vocabulary:
            choices(f"{where}: span '{span['id']}' label", span["label"], tuple(vocabulary))
        span["over"] = [str(o) for o in (span["over"] if isinstance(span["over"], list) else [span["over"]])]
        if not span["over"]:
            raise DeclarationError(f"{where}: span '{span['id']}' stands over nothing; over names bands, or glyphs and groups of one band")
        for item in span["over"]:  # whole bands, or the glyphs and groups of one band the span stands over
            if ids.get(item) is None:
                choices(f"{where}: span '{span['id']}' over", item, tuple(ids))
        out["spans"].append(span)
    out["edges"] = []
    for e in content.get("edges") or []:
        via = e.get("via") if isinstance(e, dict) else None
        edge = entry(
            {k: v for k, v in e.items() if k != "via"} if isinstance(e, dict) else e,
            ("from", "to"),
            where,
            "edge",
            optional={"kind": EDGE_KINDS[0], "label": ""},
        )
        if via is not None:  # waypoints the edge routes through, in page coordinates: `via: [[x, y], ...]`
            if not isinstance(via, list) or not all(isinstance(p, list) and len(p) == 2 for p in via):
                raise DeclarationError(f"{where}: edge {edge['from']} -> {edge['to']} via is a list of [x, y] points")
            edge["via"] = [[int(p[0]), int(p[1])] for p in via]
        if edge["kind"] not in EDGE_KINDS:
            choices(f"{where}: edge {edge['from']} -> {edge['to']} kind", edge["kind"], EDGE_KINDS)
        for end in ("from", "to"):  # an edge joins glyphs or groups: a call into a function frame ends on the frame
            if ids.get(edge[end]) not in ("glyph", "group"):
                choices(f"{where}: edge {end}", edge[end], [i for i, k in ids.items() if k in ("glyph", "group")])
        out["edges"].append(edge)
    if lens in (ACTION_LENS, PROOF_LENS):
        action_content(content, out, ids, where, lens)
    out["markers"] = []
    edge_keys = [f"{e['from']}->{e['to']}" for e in out["edges"]]
    for m in content.get("markers") or []:
        corner = m.get("corner") if isinstance(m, dict) else None
        marker = entry({k: v for k, v in m.items() if k != "corner"} if isinstance(m, dict) else m, ("at", "number"), where, "marker")
        # A marker numbers a glyph, a group, a whole band, or an edge named `from->to` (it sits on the edge's middle).
        if ids.get(marker["at"]) is None and marker["at"] not in edge_keys:
            choices(f"{where}: marker at", marker["at"], tuple(ids) + tuple(edge_keys))
        marker["number"] = int(marker["number"])
        if corner is not None:
            if corner not in CORNERS:
                choices(f"{where}: marker {marker['number']} corner", corner, CORNERS)
            marker["corner"] = corner
        out["markers"].append(marker)
    # A rule chip names a rule the diagram covers and prints its number in about.adrs; dashed (gated: false) when no gate checks it.
    # A count chip prints a number. Either sits on a glyph, a group or a band.
    out["chips"] = []
    for c in content.get("chips") or []:
        chip_kind = c.get("kind") if isinstance(c, dict) else None
        if chip_kind == "rule":
            gated = c.get("gated", True) is not False
            chip = entry({k: v for k, v in c.items() if k not in ("gated", "corner")}, ("at", "kind", "rule"), where, "chip")
            if not gated:
                chip["gated"] = False
        elif chip_kind == "count":
            chip = entry({k: v for k, v in c.items() if k != "corner"}, ("at", "kind", "text"), where, "chip")
        else:
            choices(f"{where}: chip kind", chip_kind, ("rule", "count"))
        if ids.get(chip["at"]) is None:
            choices(f"{where}: chip at", chip["at"], tuple(ids))
        corner = c.get("corner") if isinstance(c, dict) else None
        if corner is not None:
            if corner not in CORNERS:
                choices(f"{where}: chip at '{chip['at']}' corner", corner, CORNERS)
            if corner != CHIP_CORNER[chip["kind"]]:
                chip["corner"] = corner
        out["chips"].append(chip)
    legend = content.get("legend", "auto")
    if legend == "used" and lens != ACTION_LENS:
        raise DeclarationError(f"{where}: legend: used lists the operators an action diagram draws; this diagram's lens is {lens}")
    if legend not in ("auto", "used"):
        phrases = legend_phrases()
        if not isinstance(legend, list):
            raise DeclarationError(f"{where}: legend is auto or a list of the phrases the legend shows")
        for phrase in legend:
            if phrase not in phrases:
                choices(f"{where}: legend phrase", phrase, phrases)
    out["legend"] = legend
    # The one relationship the flow edges mean on this diagram, named in the legend as `flow: <relation>`.
    out["relation"] = str(content.get("relation", "") or "").strip()
    # What the thick edges reach on this diagram, the legend's phrase for them; empty keeps the library's `to a named set`.
    out["thick"] = str(content.get("thick", "") or "").strip()
    # The three minimaps: the ones the declaration names, or, when it names none, the kind's defaults maps.yml declares, which reach
    # the kit as the folder's minimap data (with_data).
    allowed = tuple(str(DEFAULTS["minimaps"]["ids"]).replace(",", " ").split())
    declared = content.get("minimaps") or []
    # The declaration holds a minimap's inputs only, never its cells: each shown minimap is an id, or { id: { exclude: [cells] } } naming
    # the lit cells its author rejects; the lit cells are computed at build from about.adrs and the citing files.
    if not isinstance(declared, list):
        raise DeclarationError(
            f"{where}: minimaps is a list of the shown minimaps, each an id or {{ id: {{ exclude: [cells] }} }}, never the cells they light"
        )
    if declared and len(declared) != 3:
        raise DeclarationError(f"{where}: minimaps names exactly three views of: {', '.join(allowed)}; it names {len(declared)}")
    out["minimaps"] = []
    for shown in declared:
        if isinstance(shown, dict):
            if len(shown) != 1:
                raise DeclarationError(f"{where}: minimaps lists an entry of {len(shown)} keys; each entry is one id")
            ((view, inputs),) = shown.items()
            inputs = inputs or {}
            if not isinstance(inputs, dict) or set(inputs) - {"exclude"}:
                raise DeclarationError(f"{where}: minimaps.{view} takes only exclude:, a list of the lit cells its author rejects")
            exclude = inputs.get("exclude") or []
            if not isinstance(exclude, list) or not all(isinstance(c, str) and c.strip() for c in exclude):
                raise DeclarationError(f"{where}: minimaps.{view} exclude: is a list of cells, each its axis values joined by /")
            if len(set(exclude)) != len(exclude):
                raise DeclarationError(f"{where}: minimaps.{view} excludes a cell twice")
        else:
            view, exclude = shown, []
        if view not in allowed:
            choices(f"{where}: minimap view", view, allowed)
        if str(view) in shown_minimaps(out["minimaps"]):
            raise DeclarationError(f"{where}: minimaps names '{view}' twice")
        out["minimaps"].append({str(view): {"exclude": [str(c) for c in exclude]}} if exclude else str(view))
    # What the diagram is about: the lens it is drawn through and the ADR codes every minimap is computed from, each checked against
    # the ADR registry.
    about = {"lens": lens, **{key: [str(v) for v in (about_raw.get(key) or [])] for key in minimaps.ABOUT_KEYS}}
    for problem in minimaps.problems(about):
        raise DeclarationError(f"{where}: {problem}")
    out["adrs"] = about["adrs"]
    # An action diagram's proof: the accosted file that holds every effect's observation, named relative to the repository root. The
    # drawing cannot carry it, so get leaves it out and save keeps the source's; Test-Diagrams is where it is required and proven.
    proves = about_raw.get("proves")
    if proves is not None and lens != ACTION_LENS:
        raise DeclarationError(f"{where}: about.proves names an action diagram's proof file; this diagram's lens is {lens}")
    if proves is not None:
        if not isinstance(proves, str) or not proves.strip():
            raise DeclarationError(f"{where}: about.proves is the repository path of a <name>.accosted.yml file")
        about["proves"] = proves.strip()
    for chip in out["chips"]:
        if chip["kind"] == "rule" and chip["rule"] not in about["adrs"]:
            choices(f"{where}: rule chip at '{chip['at']}' rule", chip["rule"], about["adrs"])
    layout = {}
    for cid, box in (raw.get("layout") or {}).items():
        if lens == ACTION_LENS and cid != "frame":  # the lens computes every place from ring and order; only the frame is pinned
            choices(f"{where}: layout cell (the action lens places every cell by ring and order)", cid, ("frame",))
        if cid not in ids:
            choices(f"{where}: layout cell", cid, tuple(ids))
        if not isinstance(box, dict) or set(box) != {"x", "y", "w", "h"}:
            raise DeclarationError(f"{where}: layout '{cid}' is a map of x, y, w and h")
        layout[cid] = {k: int(box[k]) for k in ("x", "y", "w", "h")}
    # What the diagram shows, in a sentence or two, for whoever meets it outside any article; no article is named here.
    description = " ".join(str(raw.get("description", "") or "").split())
    return {"description": description, "about": about, "content": out, "layout": layout}


def contract_call(raw, where, what):
    """One command in the contract form (ADR-AUTO-ACCOSTED-COMMANDFORM): a mapping of one key, a command's name in the normal form, to
    its arguments, each one literal under its parameter's name; `name:` alone is a call without arguments. The kit checks the shape
    alone and runs nothing: Test-Diagrams proves the name and its arguments against the command contract (ADR-AUTO-ACCOSTED-ONEREADER)."""
    if isinstance(raw, str):
        raw = {raw: None}
    if not isinstance(raw, dict) or len(raw) != 1:
        raise DeclarationError(f"{where}: {what} is one command in the contract form, `name: {{ parameter: literal }}`")
    ((name, args),) = raw.items()
    if not re.fullmatch(r"[a-z][a-z0-9_]*", str(name)):
        raise DeclarationError(f"{where}: {what} names '{name}'; a command's name is in the repository normal form, snake_case")
    if args is None:
        args = {}
    if not isinstance(args, dict):
        raise DeclarationError(f"{where}: {what} '{name}' takes a map of parameter: literal")
    for parameter, value in args.items():
        if isinstance(value, (dict, list)) or value is None:
            raise DeclarationError(f"{where}: {what} '{name}' {parameter} is one literal, never a list, a map or empty")
    return {str(name): {str(k): v for k, v in args.items()}}


def call_line(call):
    """A contract-form command as the one line the drawing prints: `name: { parameter: literal }`, or the name alone."""
    ((name, args),) = call.items()
    return f"{name}: {_flow(args)}" if args else name


def wrap_line(line, per):
    """A printed line wrapped to at most `per` characters a line at its natural breaks: after a `/`, a `,` or a space first, and only
    when a piece is still too long, after a `.` (a path such as `pwsh/Catzc.Base.Contracts/accosted/contracts.accosted.yml` has no
    space to break at). The drawing prints the lines; get joins them back with unwrap_lines."""
    pieces = []
    for piece in re.findall(r"[^/, ]*[/, ]|[^/, ]+", line):
        pieces.extend(re.findall(r"[^.]*\.|[^.]+", piece) if len(piece) > per else [piece])
    # A `key: value` whose value is long starts the value on its own line, so a path reads as one value under its key rather than as
    # a tail broken off the key; a value is long when it would not fit beside its key in half a line.
    forced = set()
    for i, piece in enumerate(pieces):
        if piece.endswith(": "):
            value = 0
            for later in pieces[i + 1 :]:
                value += len(later.rstrip())
                if later.endswith((",", " ")):
                    break
            if value > per // 2:
                forced.add(i)
    lines, current = [], ""
    for i, piece in enumerate(pieces):
        if current and len(current) + len(piece.rstrip()) > per:
            lines.append(current.rstrip())
            current = ""
        current += piece
        if i in forced and current.strip():
            lines.append(current.rstrip())
            current = ""
    if current.strip():
        lines.append(current.rstrip())
    return lines or [""]


def unwrap_lines(text):
    """The one line a drawing's wrapped text prints: a line ending in `/` or `.` continues without a space, any other with one."""
    out = ""
    for line in text.split("\n"):
        line = line.strip()
        out += line if not out or out.endswith(("/", ".")) else " " + line
    return out


def parse_call(line):
    """The call a drawing's line prints, back in the contract form."""
    try:
        raw = yaml.safe_load(unwrap_lines(line))
    except yaml.YAMLError as error:
        raise DeclarationError(f"get cannot read `{line}` as a contract-form call: {error}") from None
    return {raw: None} if isinstance(raw, str) else raw


def cause_sizes():
    """The named sizes of the cause's half-disc, each its radius, from drawio.yml action-lens cause-sizes: `name radius, ...`."""
    return {name: int(radius) for name, radius in (pair.split() for pair in str(ACTION["cause-sizes"]).split(","))}


def cause_radius(cause):
    """The radius the cause draws with: its written size, else the largest when its label ends in `!`, else the configured default."""
    sizes = cause_sizes()
    size = cause.get("size") or (max(sizes, key=sizes.get) if str(cause["label"]).rstrip().endswith("!") else str(ACTION["cause-size"]))
    return sizes[size]


def action_content(content, out, ids, where, lens=ACTION_LENS):
    """The action lens's content: its cause (the actor or trigger, in plain words), its action (one contract-form call, or a call site
    of several, drawn one row each) and its effects, each a note in a zone with its where chip and the observation that proves it; the
    proof lens takes the action alone."""
    for key in ("action",) if lens == PROOF_LENS else ACTION_KEYS:
        if key not in content:
            raise DeclarationError(f"{where}: the {lens} lens needs content.{key}")
    action_raw = content["action"]
    if not isinstance(action_raw, dict) or set(action_raw) not in ({"call"}, {"calls"}):
        raise DeclarationError(f"{where}: content.action is `call: <one command>` or `calls: [<commands>]`, never both or neither")
    if "call" in action_raw:
        action = {"call": contract_call(action_raw["call"], where, "action.call")}
    else:
        calls = action_raw["calls"]
        if not isinstance(calls, list) or len(calls) < 2:
            raise DeclarationError(f"{where}: content.action.calls is a call site of two or more commands; one command is `call:`")
        action = {"calls": [contract_call(c, where, f"action.calls[{n}]") for n, c in enumerate(calls)]}
    ids["action"] = "action"
    if lens == PROOF_LENS:
        out["action"] = action
        return
    # Whether the action diagram draws its Proof box; the default is declared once, and the key is kept only when it differs.
    proof = str(content.get("proof", "shown" if PROOF_SHOWN else "hidden"))
    if proof not in ("shown", "hidden"):
        choices(f"{where}: content.proof", proof, ("shown", "hidden"))
    if (proof == "shown") != PROOF_SHOWN:
        out["proof"] = proof
    # The cause's half-disc has a named size from the closed list in drawio.yml, the default when none is given; a label ending in `!`
    # takes the largest. The size is kept only when written, so the yml stays minimal and get gives it back the same way.
    cause = entry(content["cause"], ("label",), where, "cause", optional={"size": ""})
    sizes = cause_sizes()
    if cause["size"] and cause["size"] not in sizes:
        choices(f"{where}: cause size", cause["size"], tuple(sizes))
    if not cause["size"]:
        cause.pop("size")
    effects_raw = content["effects"]
    if not isinstance(effects_raw, list) or not effects_raw:
        raise DeclarationError(f"{where}: content.effects is a list of the action's effects, one or more")
    # The diagram's where: every effect's unless it says otherwise; kept only when it differs from the default declared once.
    diagram_where = str(content.get("where", DEFAULT_WHERE))
    if diagram_where not in WHERES:
        choices(f"{where}: content.where", diagram_where, WHERES)
    if diagram_where != DEFAULT_WHERE:
        out["where"] = diagram_where
    for cid in ("frame", "cause", "action"):
        ids[cid] = cid
    # An effect sits in a zone, the causal hop: zone 1 is what the action changes directly, zone 2 what those changes cause, and so on;
    # the effects of one zone ran in parallel. An effect follows the action, or, with after:, an effect declared before it in its own
    # zone or an inner one: an effect only goes forward. The declared order is the story's order, numbered on the drawing.
    effects = []
    for raw in effects_raw:
        # An effect is a state change (says, and the observation that proves it) or an execution (call, a further contracted command
        # the story triggers, with optional words); the edge into it says which: effects for a state change, affects for an execution.
        execution = isinstance(raw, dict) and "call" in raw
        keys = ("id", "zone", "call") if execution else ("id", "zone", "says", "proves")
        if where == "the drawing":  # a note shows only what its show: says; get cannot read the rest, and save keeps the source's
            keys = ("id", "zone")
        optional = {"where": "", "show": "", "after": "", **({k: "" for k in ("says", "proves", "call") if k not in keys})}
        effect = entry(raw, keys, where, "effect", optional=optional)
        if effect["id"] in ids:
            raise DeclarationError(f"{where}: id '{effect['id']}' is used twice")
        if not str(effect["zone"]).isdigit() or int(effect["zone"]) < 1:
            raise DeclarationError(f"{where}: effect '{effect['id']}' zone is the causal hop, 1 or more; it is {effect['zone']}")
        effect["zone"] = int(effect["zone"])
        # An effect's where is the diagram's unless it says otherwise, and the key is kept only where it differs, as its chip is drawn.
        if effect["where"] and effect["where"] not in WHERES:
            choices(f"{where}: effect '{effect['id']}' where", effect["where"], WHERES)
        if not effect["where"] or effect["where"] == diagram_where:
            effect.pop("where")
        # What the note prints; the default is declared once, and the key is kept only where it differs.
        if effect["show"] and effect["show"] not in SHOWS:
            choices(f"{where}: effect '{effect['id']}' show", effect["show"], SHOWS)
        if not effect["show"] or effect["show"] == DEFAULT_SHOW:
            effect.pop("show")
        if effect.get("show") == "words" and not str(effect.get("says", "")).strip():
            raise DeclarationError(f"{where}: effect '{effect['id']}' shows words alone but says nothing")
        if where == "the drawing":  # whatever the note printed; the source keeps what its show: hid
            for key in ("call", "proves"):
                if raw.get(key) is not None:
                    effect[key] = contract_call(raw[key], where, f"effect '{effect['id']}' {key}")
                else:
                    effect.pop(key, None)
            if not str(effect.get("says", "")).strip():
                effect.pop("says", None)
        elif execution:
            effect["call"] = contract_call(raw.get("call"), where, f"effect '{effect['id']}' call")
            if not effect["says"].strip():
                effect.pop("says")
        else:
            if not effect["says"].strip():
                raise DeclarationError(f"{where}: effect '{effect['id']}' says nothing; says is the state it changes, in plain words")
            effect["proves"] = contract_call(raw.get("proves"), where, f"effect '{effect['id']}' proves")
        effect = {k: effect[k] for k in EFFECT_KEYS if k in effect and effect[k] != ""}  # an optional key left empty is absent
        after = effect.pop("after", "")
        if after:
            earlier = next((e for e in effects if e["id"] == after), None)
            if earlier is None:
                choices(f"{where}: effect '{effect['id']}' after (an effect declared before it)", after, [e["id"] for e in effects])
            if earlier["zone"] > effect["zone"]:
                raise DeclarationError(
                    f"{where}: effect '{effect['id']}' in zone {effect['zone']} comes after '{after}' in zone {earlier['zone']}; "
                    "an effect only goes forward, to its own zone or an outer one"
                )
            effect["after"] = after
        ids[effect["id"]] = "effect"
        effects.append(effect)
    zones = sorted({e["zone"] for e in effects})
    if zones != list(range(1, len(zones) + 1)):
        raise DeclarationError(f"{where}: the zones are the causal hops 1, 2, …, each with an effect; the effects name {zones}")
    # The canonical order is by zone, then as declared: the story's order, which the drawing numbers.
    out["cause"], out["action"], out["effects"] = cause, action, sorted(effects, key=lambda e: e["zone"])


def entry(item, keys, where, what, optional=None):
    if not isinstance(item, dict):
        raise DeclarationError(f"{where}: a {what} is a map of {', '.join(keys)}")
    allowed = tuple(keys) + tuple(optional or ())
    for key in item:
        if key not in allowed:
            choices(f"{where}: {what} key", key, allowed)
    out = {}
    for key in keys:
        if key not in item or item[key] in (None, ""):
            raise DeclarationError(f"{where}: a {what} needs {key}")
        out[key] = item[key] if isinstance(item[key], list) else str(item[key])
    for key, default in (optional or {}).items():
        out[key] = str(item.get(key, default))
    return out


def brief(phrase):
    """A legend phrase as the legend prints it: the name alone, without the explanation in parentheses or after a colon; a flow keeps
    its relation, a commit its state and an operator its meaning, which are the names."""
    if phrase.startswith(("flow: ", "commit: ", "execution: ", "proof: ") + tuple(f"{word}: " for word in OPERATORS)):
        return phrase.split(" (")[0] if not phrase.startswith("commit: ") else phrase
    return phrase.split(" (")[0].split(":")[0].strip()


def legend_phrases():
    return tuple(
        [g["phrase"] for g in LIB["glyphs"].values()]
        + [e["phrase"] for e in LIB["edges"].values()]
        + [m["phrase"] for m in LIB["marks"].values()]
    )


def dump(declaration):
    """The whole declaration as the text of its source file, keys in the kit's order."""
    content = dict(declaration["content"])
    # A row's written-out cells are its expansion, never the source: the row is written, and they are left out.
    generated = declaration.get("generated") or content.get("generated") or set()
    if generated:
        for key in ("groups", "glyphs"):
            content[key] = [i for i in content[key] if i["id"] not in generated]
        content["edges"] = [e for e in content["edges"] if e["from"] not in generated or e["to"] not in generated]
    ordered = {k: content[k] for k in CONTENT_KEYS if k in content and content[k] not in ([], {}, "")}
    out = {"description": declaration["description"]} if declaration.get("description") else {}
    about = declaration.get("about") or {}
    out["about"] = {key: about[key] for key in ABOUT_KEYS if about.get(key)}
    out["content"] = ordered
    if declaration.get("layout"):
        out["layout"] = dict(declaration["layout"])
    return flow_yaml(out, print_width())


def print_width(root=None):
    """The longest printed line: max_line_length under [*.md] in the repository root's .editorconfig, read at print time, never copied."""
    path = Path(root or KIT.parents[1]) / ".editorconfig"
    if not path.is_file():
        raise DeclarationError(f"{path}: not found, so the print width ([*.md] max_line_length) cannot be read")
    section = None
    for line in path.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if line.startswith("[") and line.endswith("]"):
            section = line[1:-1]
        elif section == "*.md" and "=" in line:
            key, value = (part.strip() for part in line.split("=", 1))
            if key == "max_line_length":
                return int(value)
    raise DeclarationError(f"{path}: the section [*.md] has no max_line_length, the print width")


def flow_yaml(data, width):
    """The data in block style, each leaf mapping or list whose whole line fits the width printed as one flow line in Prettier's form."""
    lines = []
    _block(data, 0, width, lines)
    return "\n".join(lines) + "\n"


def _flow_scalar(value, flow=True):
    # A scalar quoted where yaml.safe_dump quotes it, inside a flow collection (where a plain `,` or `[` would end it) or in block style;
    # a quoted one takes Prettier's double quotes when its text holds no `"` or `\` to escape.
    dumped = yaml.safe_dump([value], default_flow_style=flow, allow_unicode=True, width=10**9).strip()
    text = dumped[1:-1] if flow else dumped[2:]
    if text.startswith("'") and isinstance(value, str) and '"' not in value and "\\" not in value and value.isprintable():
        return f'"{value}"'
    return text


def _flow(node):
    """The node as one flow line, or None when it is not a leaf: a child is a collection or a string of several lines."""
    children = node.values() if isinstance(node, dict) else node
    if any(isinstance(c, (dict, list)) or (isinstance(c, str) and "\n" in c) for c in children):
        return None
    if isinstance(node, dict):
        return "{ " + ", ".join(f"{_flow_scalar(k)}: {_flow_scalar(v)}" for k, v in node.items()) + " }"
    return "[" + ", ".join(_flow_scalar(v) for v in node) + "]"


def _scalar_lines(key, value, indent, width):
    """A scalar under its key, or a list item when the key is None, as Prettier prints it: on the key's or dash's line when it fits, else
    a plain text filled word by word at the width, under the key or beside the dash; any other long scalar as yaml.safe_dump writes it."""
    pad = " " * indent
    lead = "-" if key is None else f"{_flow_scalar(key, flow=False)}:"
    text = _flow_scalar(value, flow=False)
    if "\n" not in text and len(pad + lead) + 1 + len(text) <= width or not isinstance(value, str):
        return [f"{pad}{lead} {text}"]
    words = value.split(" ")
    if _double_quotable(value) and (text[0] in "'\"" or "\n" in value):
        return _quoted_lines(lead, value, pad, width)
    if text[0] in "'\"" or "\n" in value or "" in words:
        wrapped = [value] if key is None else {key: value}
        dumped = yaml.safe_dump(wrapped, sort_keys=False, allow_unicode=True, width=max(width - indent, 20))
        return [pad + line for line in dumped.splitlines() if line != "..."]
    lines = [] if key is None else [f"{pad}{lead}"]
    prefix, line = (f"{pad}- " if key is None else f"{pad}  "), []
    for word in words:
        if line and len(prefix) + len(" ".join(line + [word])) > width:
            lines.append(prefix + " ".join(line))
            prefix, line = f"{pad}  ", []
        line.append(word)
    lines.append(prefix + " ".join(line))
    return lines


def _double_quotable(value):
    # Prettier folds a text into double quotes when nothing in it needs an escape and its words fill back to it: single spaces, and line
    # breaks only between words, so a fold or a blank line reads back as the space or the break it stands for.
    paragraphs = value.split("\n")
    return (
        '"' not in value
        and "\\" not in value
        and value.replace("\n", "").isprintable()
        and bool(paragraphs[0])
        and bool(paragraphs[-1])
        and all(word for p in paragraphs if p for word in p.split(" "))
    )


def _quoted_lines(lead, value, pad, width):
    """A double-quoted text as Prettier prints it: beside the dash, or beside the key when it has line breaks, else under the key; each
    paragraph filled word by word at the width, without the closing quote, and each line break of the text a blank line."""
    beside = lead == "-" or "\n" in value
    lines, prefix, line = ([] if beside else [f"{pad}{lead}"]), (f'{pad}{lead} "' if beside else f'{pad}  "'), []
    for n, paragraph in enumerate(value.split("\n")):
        if n:
            if line:
                lines.append(prefix + " ".join(line))
                prefix, line = f"{pad}  ", []
            lines.append("")
        for word in paragraph.split(" ") if paragraph else []:
            if line and len(prefix) + len(" ".join(line + [word])) > width:
                lines.append(prefix + " ".join(line))
                prefix, line = f"{pad}  ", []
            line.append(word)
    lines.append(prefix + " ".join(line) + '"')
    return lines


def _block(node, indent, width, lines):
    pad = " " * indent
    if isinstance(node, dict):
        for key, value in node.items():
            lead = f"{pad}{_flow_scalar(key)}:"
            if not isinstance(value, (dict, list)):
                lines.extend(_scalar_lines(key, value, indent, width))
            elif not value:
                lines.append(f"{lead} {'{}' if isinstance(value, dict) else '[]'}")
            elif (flow := _flow(value)) and len(lead) + 1 + len(flow) <= width:
                lines.append(f"{lead} {flow}")
            else:
                lines.append(lead)
                _block(value, indent + 2, width, lines)
        return
    for item in node:
        if not isinstance(item, (dict, list)):
            lines.extend(_scalar_lines(None, item, indent, width))
        elif not item:
            lines.append(f"{pad}- {'{}' if isinstance(item, dict) else '[]'}")
        elif (flow := _flow(item)) and indent + 2 + len(flow) <= width:
            lines.append(f"{pad}- {flow}")
        elif isinstance(item, dict):
            inner = []
            _block(item, indent + 2, width, inner)
            lines.append(f"{pad}- {inner[0][indent + 2 :]}")
            lines.extend(inner[1:])
        else:
            lines.append(f"{pad}-")
            _block(item, indent + 2, width, lines)


# ---- put: the declaration becomes the model ------------------------------------------------------------------------


def cell(cid, value, style, x, y, w, h, parent="1"):
    return {"id": cid, "value": value, "style": style, "x": x, "y": y, "w": w, "h": h, "parent": parent, "edge": None}


def edge_cell(cid, value, style, source, target):
    return {"id": cid, "value": value, "style": style, "source": source, "target": target, "parent": "1", "edge": True}


LAYERS = tuple(DEFAULTS["layers"])  # the paint order, back to front, declared once in drawio.yml


def layer_of(c):
    """The paint layer of a placed cell, one of LAYERS."""
    style = c["style"]
    if c["edge"]:
        return "lines" if c["id"].startswith("lane-") or style_map(style).get("curved") == "1" else "edges"
    if c["id"] in ("sidebar-bg", "mapkey") or style in (BAND, LEGEND, NOTE):
        return "panels"
    if style == LIB["module"]:
        return "frames"
    if "shape=crossbar" in style:
        return "spans"
    if c["id"].startswith(("mark-", "chip-")) or c["id"].endswith("-tag"):
        return "marks"
    return "labels" if style.startswith("text;") else "glyphs"


def in_paint_order(cells):
    """The cells as draw.io paints them: each parent, then its children back to front by LAYERS. draw.io paints a frame's whole
    contents where the frame stands, so an edge moves into a frame that holds no frame of its own, where it paints before every glyph:
    the innermost frame holding both its ends when that frame holds none, else the first such frame painted. A legend swatch stays."""
    rank = {layer: n for n, layer in enumerate(LAYERS)}

    def tree():
        children: dict = {}
        for c in cells:
            children.setdefault(c["parent"], []).append(c)
        ordered = []

        def walk(pid):
            for c in sorted(children.get(pid, []), key=lambda c: rank[layer_of(c)]):
                ordered.append(c)
                walk(c["id"])

        walk("1")
        return ordered

    parent_of = {c["id"]: c["parent"] for c in cells if not c["edge"]}
    frames = {c["id"] for c in cells if not c["edge"] and layer_of(c) == "frames"}
    leaves = [c["id"] for c in tree() if c["id"] in frames and not any(parent_of.get(f) == c["id"] for f in frames)]

    def frames_of(cid):  # the frames around a cell, innermost first
        chain = []
        while parent_of.get(cid, "1") != "1":
            cid = parent_of[cid]
            if cid in frames:
                chain.append(cid)
        return chain

    for c in cells:
        if c["edge"] and leaves and not c["id"].startswith("lg-"):
            shared = [f for f in frames_of(c["source"]) if f in frames_of(c["target"])]
            c["parent"] = shared[0] if shared and shared[0] in leaves else leaves[0]
    ordered = tree()
    placed = {id(c) for c in ordered}
    return ordered + [c for c in cells if id(c) not in placed]


def chrome(content, cells):
    """The chrome every diagram opens with: the lens once, as the chip that opens the title row, the title, and under it the subtitle,
    the ADR codes alone. Returns how far a wrapped subtitle drops the drawing area."""
    chip_w = 16 + 8 * len(content["lens"])
    cells.append(cell("lens-badge", content["lens"].upper(), BADGE, PAGE["x"], PAGE["title_y"] + 4, chip_w, 22))
    title_x = PAGE["x"] + chip_w + 12
    cells.append(
        cell(
            "title", html.escape(content["title"], quote=False), TITLE, title_x, PAGE["title_y"], PAGE["width"] - (title_x - PAGE["x"]), 30
        )
    )
    subtitle = " · ".join(content["adrs"])
    lines = max(1, -(-len(subtitle) * 7 // (PAGE["width"] - 20)))  # about 7 px a character at 12 px
    drop = (lines - 1) * 16  # the grid starts the bands this much lower under a wrapped subtitle
    cells.append(cell("subtitle", subtitle, SUBTITLE, PAGE["x"], PAGE["subtitle_y"] - 4, PAGE["width"] - 20, 18 + lines * 16))
    return drop


def place(declaration):
    """Every cell of the model with its absolute geometry: the grid places what the layout does not name; the action lens places
    everything by ring and order."""
    content, layout = declaration["content"], declaration["layout"]
    if content["lens"] in (ACTION_LENS, PROOF_LENS):
        return place_action(declaration)
    glyph_lib = LIB["glyphs"]
    holder = {}
    for item in content["groups"] + content["glyphs"] + content.get("notes", []):
        holder.setdefault(item["in"], []).append(item)
    rows = {r["id"]: r for r in content.get("rows") or []}
    lanes = {str(l["band"]): l for l in content.get("lanes") or []}

    def size_of(item):
        if item["id"] in layout:
            return layout[item["id"]]["w"], layout[item["id"]]["h"]
        if "text" in item:  # a note: its width, and a line of height per line of text at the width
            lines = sum(max(1, math.ceil(len(line) / 62)) for line in item["text"].split("\n"))
            return NOTE_WIDTH, 24 + 16 * lines
        if item.get("shape") == "box":
            return COMMIT_BOX_SIZE
        if "kind" in item:
            return glyph_lib[item["kind"]]["size"]
        inner_w, inner_h = grid_size(item["id"])
        return inner_w + 2 * PAD, inner_h + LABEL_ROW + PAD

    def lane_xy(band_id, step, row):
        """Where a lane's commit at a step and row sits: the steps spread evenly along the band, row 0 on the trunk, +1 above it."""
        bb, lane = band_box[band_id], lanes[band_id]
        dot = glyph_lib["commit"]["size"][0]
        left, right = bb["x"] + PAD + 40, bb["x"] + bb["w"] - PAD - 60 - dot
        stride = (right - left) / (int(lane["steps"]) - 1)
        mid = bb["y"] + LABEL_ROW + (bb["h"] - LABEL_ROW - PAD) // 2 - dot // 2
        return round(left + (step - 1) * stride), mid - row * LANE_ROW

    def row_place(holder_id, item, origin_x, origin_y, w, h):
        """A row's dot n sits in column n, its drop under it; a lane's commit at its step and row; anything else in the holder is
        placed by the grid."""
        if holder_id in lanes:
            lane = lanes[holder_id]
            placed = next((c for c in (lane.get("commits") or []) + (lane.get("glyphs") or []) if str(c["id"]) == item["id"]), None)
            if placed is not None:  # centred on its step's column, as a commit dot is
                x, y = lane_xy(holder_id, int(placed["step"]), int(placed.get("row", 0)))
                dot = glyph_lib["commit"]["size"]
                return {"x": x + dot[0] // 2 - w // 2, "y": y + dot[1] // 2 - h // 2, "w": w, "h": h}
        if holder_id not in rows:
            return None
        rest = item["id"][len(holder_id) + 1 :]
        n, _, drop = rest.partition("-")
        if not n.isdigit():
            return None
        return {"x": origin_x + int(n) * ROW_PITCH, "y": origin_y + (ROW_DROP if drop else 0), "w": w, "h": h}

    def grid_size(holder_id, width=None):
        if holder_id in rows:  # its dots in a line, its drops in the line under it
            dot = glyph_lib["commit"]["size"]
            return len(rows[holder_id]["steps"]) * ROW_PITCH + dot[0], ROW_DROP + dot[1]
        if holder_id in lanes:  # a lane's height is fixed: its trunk and a branch row above and below it
            return 0, LANE_HEIGHT - LABEL_ROW - PAD
        items = holder.get(holder_id, [])
        if not items:
            return 0, 0
        sizes = [size_of(i) for i in items]
        if width is None:
            columns = max(1, min(len(items), 4))
            width = sum(s[0] for s in sizes[:columns]) + COL_GAP * (columns - 1)
        x = y = row_h = 0
        total_w = 0
        for w, h in sizes:
            if x > 0 and x + w > width:
                y += row_h + ROW_GAP
                x, row_h = 0, 0
            x += w + COL_GAP
            row_h = max(row_h, h)
            total_w = max(total_w, x - COL_GAP)
        return total_w, y + row_h

    vertical = content["flow"] == "top-to-bottom"
    has_spans = bool(content["spans"])
    # A span over whole bands stands beside them in a top-to-bottom flow; a span over glyphs of one band lies above that band.
    upright = lambda s: vertical and any(o in {b["id"] for b in content["bands"]} for o in s["over"])
    bands = content["bands"]
    cells = []
    drop = chrome(content, cells)
    # The bands along the flow: side by side left to right, or stacked top to bottom.
    band_box = {}
    if vertical:
        left = PAGE["x"] + (50 if any(upright(s) for s in content["spans"]) else 0)
        width = PAGE["width"] - (left - PAGE["x"])
        y = PAGE["band_y"] - (24 if not has_spans else 0) + drop
        for b in bands:
            inner_h = grid_size(b["id"], width - 2 * PAD)[1]
            h = max(inner_h + LABEL_ROW + PAD, 120)
            band_box[b["id"]] = layout.get(b["id"], {"x": left, "y": y, "w": width, "h": h})
            y = band_box[b["id"]]["y"] + band_box[b["id"]]["h"] + GAP
        content_bottom = y - GAP
    else:
        n = max(1, len(bands))
        width = (PAGE["width"] - GAP * (n - 1)) // n
        inner = [grid_size(b["id"], width - 2 * PAD) for b in bands]
        h = max([i[1] + LABEL_ROW + PAD for i in inner] + [120])
        top = (PAGE["band_y"] if has_spans else PAGE["band_y"] - 24) + drop
        x = PAGE["x"]
        for b in bands:
            band_box[b["id"]] = layout.get(b["id"], {"x": x, "y": top, "w": width, "h": h})
            x = band_box[b["id"]]["x"] + band_box[b["id"]]["w"] + GAP
        content_bottom = max([bb["y"] + bb["h"] for bb in band_box.values()] + [top])
    for b in bands:
        bb = band_box[b["id"]]
        cells.append(cell(b["id"], html.escape(b["label"], quote=False), BAND, bb["x"], bb["y"], bb["w"], bb["h"]))
    # The groups and glyphs inside their holders, by the grid unless the layout places them.
    box_of = dict(band_box)

    def fill(holder_id, origin_x, origin_y, width, parent):
        x = y = row_h = 0
        for item in holder.get(holder_id, []):
            w, h = size_of(item)
            if x > 0 and x + w > width:
                y += row_h + ROW_GAP
                x, row_h = 0, 0
            box = (
                layout.get(item["id"])
                or row_place(holder_id, item, origin_x, origin_y, w, h)
                or {"x": origin_x + x, "y": origin_y + y, "w": w, "h": h}
            )
            box_of[item["id"]] = box
            if item["id"] in layout and holder_id in band_box:  # a band holds its items by place alone, so a moved item names its band
                cx, cy = box["x"] + box["w"] / 2, box["y"] + box["h"] / 2
                within = [b for b, bb in band_box.items() if bb["x"] <= cx <= bb["x"] + bb["w"] and bb["y"] <= cy <= bb["y"] + bb["h"]]
                if within and holder_id not in within:
                    raise DeclarationError(
                        f"layout places '{item['id']}' in {within[0]}, but its in: is {holder_id}; set in: to the band it "
                        f"sits in, or move it back"
                    )
            if "text" in item:
                text = "<br>".join(html.escape(line, quote=False) for line in item["text"].split("\n"))
                cells.append(cell(item["id"], text, NOTE, box["x"], box["y"], box["w"], box["h"], parent))
            elif "kind" in item:
                style = COMMIT_BOX if item.get("shape") == "box" else glyph_lib[item["kind"]]["style"]
                if item["kind"] == "env" and holder.get(item["id"]):  # an occupied environment names itself left of its occupants
                    style += "align=left;spacingLeft=22;"
                if item["kind"] == "commit":
                    style = commit_style(style, item.get("state", COMMIT_STATES[0]), item.get("ghost", False))
                label = "<br>".join(html.escape(line, quote=False) for line in item["label"].split("\n"))  # a box's second line
                cells.append(cell(item["id"], f"<b>{label}</b>", style, box["x"], box["y"], box["w"], box["h"], parent))
                if item["kind"] == "type":
                    tag = glyph_lib["type"]["tag"]
                    cells.append(
                        cell(
                            f"{item['id']}-tag",
                            "C#",
                            tag["style"],
                            box["x"] + box["w"] - tag["size"][0] - 8,
                            box["y"] - 8,
                            tag["size"][0],
                            tag["size"][1],
                            parent,
                        )
                    )
                # An environment's occupant commits sit inside it, right of its name, in a row from its right edge inward.
                for n, occupant in enumerate(holder.get(item["id"], [])):
                    d = glyph_lib["commit"]["size"][1]
                    inner = layout.get(occupant["id"]) or {
                        "x": box["x"] + box["w"] - 30 - d - n * (d + 6),
                        "y": box["y"] + (box["h"] - d) // 2,
                        "w": d,
                        "h": d,
                    }
                    box_of[occupant["id"]] = inner
                    occupant_style = commit_style(
                        glyph_lib["commit"]["style"], occupant.get("state", COMMIT_STATES[0]), occupant.get("ghost", False)
                    )
                    cells.append(
                        cell(
                            occupant["id"],
                            f"<b>{html.escape(occupant['label'], quote=False)}</b>",
                            occupant_style,
                            inner["x"],
                            inner["y"],
                            inner["w"],
                            inner["h"],
                            item["id"],
                        )
                    )
            else:
                cells.append(
                    cell(item["id"], html.escape(item["label"], quote=False), LIB["module"], box["x"], box["y"], box["w"], box["h"], parent)
                )
                fill(item["id"], box["x"] + PAD, box["y"] + LABEL_ROW, box["w"] - 2 * PAD, item["id"])
            x += w + COL_GAP
            row_h = max(row_h, h)

    for b in bands:
        bb = band_box[b["id"]]
        fill(b["id"], bb["x"] + PAD, bb["y"] + LABEL_ROW, bb["w"] - 2 * PAD, "1")
    # A lane's furniture, the yml's alone: its trunk line named at its end, the marks over its commits, and the gate rules across
    # every band, between two steps of the first lane.
    for lane in lanes.values():
        band, (x0, y_mid) = lane["band"], lane_xy(lane["band"], 1, 0)
        x1 = lane_xy(band, int(lane["steps"]), 0)[0]
        dot = glyph_lib["commit"]["size"][0]
        if lane.get("trunk"):
            cells.append(cell(f"lane-{band}-a", "", ANCHOR, x0 - 20, y_mid + dot // 2, 1, 1))
            cells.append(cell(f"lane-{band}-b", "", ANCHOR, x1 + dot + 20, y_mid + dot // 2, 1, 1))
            cells.append(edge_cell(f"lane-{band}-trunk", "", TRUNK, f"lane-{band}-a", f"lane-{band}-b"))
            cells.append(
                cell(
                    f"lane-{band}-trunk-label",
                    html.escape(str(lane["trunk"]), quote=False),
                    TRUNK_LABEL,
                    x1 - 160,
                    y_mid + dot + 8,
                    200,
                    18,
                )
            )
        for n, mark in enumerate(lane.get("marks") or []):
            at = box_of[str(mark["at"])]
            cells.append(
                cell(f"lane-{band}-mark-{n}", html.escape(str(mark["text"]), quote=False), MARK_TEXT, at["x"] - 70, at["y"] - 36, 162, 32)
            )
    if lanes:
        # A rule crosses the lanes that share the first lane's steps, and the bands between them; a lane on another axis (git's
        # history) runs under its own steps, so no rule crosses it.
        first = next(iter(lanes.values()))
        stride = lane_xy(first["band"], 2, 0)[0] - lane_xy(first["band"], 1, 0)[0]
        axis = [band_box[b] for b, lane in lanes.items() if int(lane["steps"]) == int(first["steps"])]
        top, bottom = min(bb["y"] for bb in axis), max(bb["y"] + bb["h"] for bb in axis)
        for n, rule in enumerate(content.get("rules") or []):
            x = lane_xy(first["band"], int(rule["after"]), 0)[0] + glyph_lib["commit"]["size"][0] // 2 + stride // 2
            cells.append(cell(f"lane-rule-{n}-a", "", ANCHOR, x, top + LABEL_ROW, 1, 1))
            cells.append(cell(f"lane-rule-{n}-b", "", ANCHOR, x, bottom, 1, 1))
            cells.append(edge_cell(f"lane-rule-{n}", "", RULE_STYLES[rule["kind"]], f"lane-rule-{n}-a", f"lane-rule-{n}-b"))
    # The span bars over (or beside) what they cover: whole bands, or glyphs and groups of one band.
    holder = {i["id"]: i["in"] for i in content["groups"] + content["glyphs"]}

    def band_of(item):
        while item in holder:
            item = holder[item]
        return item

    def reach(s):
        boxes = [box_of[i] for i in s["over"]]
        return min(b["x"] for b in boxes), max(b["x"] + b["w"] for b in boxes), boxes

    span_levels, span_cells = [], {}
    for s in sorted(content["spans"], key=lambda s: reach(s)[1] - reach(s)[0]):  # the narrow spans first, the wide ones stack above
        x0, x1, boxes = reach(s)
        if upright(s):
            y0, y1 = min(b["y"] for b in boxes), max(b["y"] + b["h"] for b in boxes)
            bar = cell(
                s["id"],
                "",
                "shape=crossbar;whiteSpace=wrap;html=1;rounded=1;fillColor=none;strokeColor=@line;strokeWidth=1.5;shadow=0;rotation=90;",
                PAGE["x"] + 12,
                y0,
                14,
                y1 - y0,
            )
            label = cell(f"{s['id']}-label", html.escape(s["label"], quote=False), SPAN_LABEL, PAGE["x"] - 4, (y0 + y1) // 2 - 8, 30, 16)
        else:
            # A span sits just above the band of what it covers, so it moves down with the bands under a wrapped subtitle; a span over
            # what an earlier span already covers stacks one level higher (CD over CI).
            taken = {lv for lx0, lx1, lv in span_levels if lx0 < x1 and x0 < lx1}
            level = min(lv for lv in range(len(taken) + 1) if lv not in taken)  # the lowest level nothing it overlaps holds
            span_levels.append((x0, x1, level))
            y = min(band_box[band_of(i)]["y"] for i in s["over"]) - 24 - level * 32
            bar = cell(
                s["id"],
                "",
                "shape=crossbar;whiteSpace=wrap;html=1;rounded=1;fillColor=none;strokeColor=@line;strokeWidth=1.5;shadow=0;",
                x0,
                y,
                x1 - x0,
                14,
            )
            label = cell(f"{s['id']}-label", html.escape(s["label"], quote=False), SPAN_LABEL, (x0 + x1) // 2 - 15, y - 18, 30, 16)
        span_cells[s["id"]] = [bar, label]
    for s in content["spans"]:  # in the declared order, so get reads them back in it
        cells.extend(span_cells[s["id"]])
    # Room for the spans: when the topmost span label would reach into the title and subtitle, the whole drawing area moves down by
    # the shortfall; the title, the subtitle and the lens chip stay where they are.
    title_room = PAGE["subtitle_y"] + (drop // 16 + 1) * 16 + 4  # the subtitle's lines, from the drop chrome returned
    labels_top = [c["y"] for c in cells if c["id"].endswith("-label") and any(c["id"] == f"{s['id']}-label" for s in content["spans"])]
    delta = max(0, title_room - min(labels_top)) if labels_top else 0
    if delta:
        for c in cells:  # every y here is absolute; to_xml makes a child's relative to its parent
            if c["id"] not in ("title", "subtitle", "lens-badge") and not c["edge"]:  # an edge follows its ends
                c["y"] += delta
        box_of = {k: {**v, "y": v["y"] + delta} for k, v in box_of.items()}
        content_bottom += delta
        # The shift moves the declared layout and waypoints too, and over laid-out bands it cannot be derived again from what is
        # drawn, so the title carries it and get takes it off again.
        next(c for c in cells if c["id"] == "title")["style"] += f"{SHIFT_KEY}={delta};"
    # Edges, markers and chips anchor on the glyphs.
    for e in content["edges"]:
        style = LIB["edges"][e["kind"]]["style"]
        if e["label"]:
            style = style.replace("shadow=0;", "fontColor=@ink;fontStyle=1;fontSize=11;labelBackgroundColor=@band;shadow=0;")
        eid = f"e-{e['from']}-{e['to']}"
        n = sum(1 for c in cells if c["id"] == eid or c["id"].startswith(eid + "~"))  # a repeat edge between the same pair: e-…~2
        edge = edge_cell(
            eid if not n else f"{eid}~{n + 1}",
            f"<b>{html.escape(e['label'], quote=False)}</b>" if e["label"] else "",
            style,
            e["from"],
            e["to"],
        )
        edge["via"] = [[x, y + delta] for x, y in e.get("via", [])]  # waypoints move with the drawing area
        if e["kind"] == "bypass":  # out of its source's side, down under the skipped dot, and up into its target's side
            a, b = box_of[e["from"]], box_of[e["to"]]
            low = a["y"] + a["h"] + BYPASS_DIP
            edge["via"] = [[a["x"] + a["w"] + BYPASS_DIP, low], [b["x"] - BYPASS_DIP, low]]
        if e["label"]:
            # A steep edge, one that climbs or falls more than it runs, never carries its word across its own line: the word stands
            # left-aligned, glued 3 px right of the line at its middle, where draw.io and the painter both put an align=left label.
            a, b = box_of[e["from"]], box_of[e["to"]]
            points = [(a["x"] + a["w"] / 2, a["y"] + a["h"] / 2), *[(x, y) for x, y in edge["via"]], (b["x"] + b["w"] / 2, b["y"] + b["h"] / 2)]
            (x0, y0), (x1, y1) = middle_leg(points)
            if abs(y1 - y0) > abs(x1 - x0):
                edge["style"] += "align=left;"
                edge["label_at"] = (0, -WORD_GAP if y1 > y0 else WORD_GAP)
        cells.append(edge)
    size = LIB["marks"]["marker"]["size"]
    for m in content["markers"]:
        if m["at"] not in box_of:  # an edge `from->to`: the marker sits halfway along its path, through its waypoints
            s, t = m["at"].split("->")
            via = next(([[x, y + delta] for x, y in e.get("via", [])] for e in content["edges"] if (e["from"], e["to"]) == (s, t)), [])
            mx, my = edge_middle(box_of[s], box_of[t], via)
            cells.append(
                cell(
                    f"mark-{m['number']}",
                    str(m["number"]),
                    LIB["marks"]["marker"]["style"],
                    round(mx - 11),
                    round(my - 11),
                    size[0],
                    size[1],
                )
            )
            continue
        box = box_of[m["at"]]
        kind = next((g["kind"] for g in content["glyphs"] if g["id"] == m["at"]), "")
        if "corner" in m:
            mx, my = marker_xy(box, m["corner"])
        elif kind == "gate":  # a diamond's corner is empty space, so its marker sits beside its top point
            mx, my = box["x"] + box["w"] // 2 - 40, box["y"] - 4
        elif not kind:  # a band or a group: just inside its top-left corner, so it never widens the page
            mx, my = box["x"] + 4, box["y"] - 11
        else:
            sources = [box_of[e["from"]] for e in content["edges"] if e["to"] == m["at"] and e["from"] in box_of]
            mx, my = marker_xy(box, auto_corner(box, sources))
        cells.append(cell(f"mark-{m['number']}", str(m["number"]), LIB["marks"]["marker"]["style"], mx, my, size[0], size[1]))
    placed, row = {}, {}
    for c in content["chips"]:
        box = box_of[c["at"]]
        mark = LIB["marks"][c["kind"]]
        k = placed[c["at"], c["kind"]] = placed.get((c["at"], c["kind"]), -1) + 1  # the chip's number on its place, for its id
        corner = c.get("corner", CHIP_CORNER[c["kind"]])
        j = row[c["at"], corner] = row.get((c["at"], corner), -1) + 1  # several chips on one corner stand in a row inward
        cx = box["x"] + 4 + j * 34 if corner.endswith("left") else box["x"] + box["w"] - 30 - j * 34
        cy = box["y"] - 9 if corner.startswith("top") else box["y"] + box["h"] - 9
        if c["kind"] == "rule":
            value, style = f"#{content['adrs'].index(c['rule']) + 1}", mark["style"] + ("" if c.get("gated", True) else "dashed=1;")
        else:
            value, style = c["text"], mark["style"]
        cells.append(cell(f"chip-{c['kind']}-{c['at']}-{k}", value, style, cx, cy, mark["size"][0], mark["size"][1]))
    return finish(cells, content, content_bottom, declaration)


def place_action(declaration):
    """The action lens's cells: one rounded frame captioned with the title; the cause, a half-disc whose flat side sits on the frame's
    left rim; the action right of it, one call or a call site of rows; the rings, one per causal hop, half-rings opening rightward from
    the cause's centre; each effect a note on its ring with its where chip, spread top to bottom in declared order; and the flow edges
    the lens draws itself, cause to action and action to each effect. Nothing but the frame takes a layout entry."""
    content, layout = declaration["content"], declaration["layout"]
    lib = LIB["glyphs"]
    cells: list = []
    drop = chrome(content, cells)
    if content["lens"] == PROOF_LENS:  # the Proof box alone, where the frame would stand
        bottom = proof_cells(cells, content["action"], PAGE["x"], PAGE["band_y"] + drop, PAGE["width"])
        return finish(cells, content, bottom, declaration)
    gap, note_w, radius = int(ACTION["ring-gap"]), int(ACTION["note-width"]), cause_radius(content["cause"])
    action, effects = content["action"], content["effects"]
    site = "calls" in action
    member = lib["callsite"]["member"]
    # Every call wraps at its natural breaks inside the action width, about 7 px a character, and the glyph grows in height to
    # hold the lines; a piece with no break left makes the glyph wider instead, and the width budget below says if that is too much.
    wrapped = [wrap_line(call_line(c), (ACTION_WIDTH - 28) // 7) for c in (action["calls"] if site else [action["call"]])]
    aw = max(lib["callsite" if site else "action"]["size"][0], 28 + 7 * max(len(line) for lines in wrapped for line in lines))
    row_h = [member["size"][1] + 16 * (len(lines) - 1) for lines in wrapped]
    ah = 30 + sum(h + 10 for h in row_h) if site else max(lib["action"]["size"][1], 24 + 16 * len(wrapped[0]))
    per_note = max(1, (note_w - 24) // 7)

    def note_lines(e):  # the says lines, which draw.io wraps itself, and the proof or call lines, wrapped here so a path breaks
        show = e.get("show", DEFAULT_SHOW)
        says = wrap_line(e["says"], per_note) if e.get("says") and show != "call" else []
        line = wrap_line(call_line(e["call"] if "call" in e else e["proves"]), per_note) if show != "words" else []
        return says, line

    def note_h(e):
        says, line = note_lines(e)
        return 24 + 16 * (len(says) + len(line))

    def operator(source, target):  # the edge's word: executes from the action, then affects into an execution, effects into a state
        return "executes" if source == "action" else "affects" if "call" in target else "effects"

    hops = max(e["zone"] for e in effects)
    if gap < note_w + PAD:  # two effects at the same angle on neighbouring rings would overlap: the kit's constants, not the author's
        raise DeclarationError(
            f"drawio.yml action-lens: ring-gap {gap} leaves no room for a note of note-width {note_w} plus {PAD}; raise ring-gap"
        )
    # The rings are centred where the cause's flat side meets the frame's left rim, so they open rightward as half-rings cut by the
    # frame; the action sits right of the cause, and the first ring clears the action's right edge.
    r0 = radius + ACTION_CLEARANCE + aw + ACTION_CLEARANCE
    r_max = r0 + hops * gap
    # The frame has a fixed height: an invisible centre lane holds the cause, the action and every note, and the margin above and
    # below it is where the rings crawl up and down before the frame cuts them. The outermost ring spans the whole inner height and
    # the inner rings scale with their radius, so few rings draw flat. A pinned frame (layout: frame) sets another height.
    frame = layout.get("frame") or {
        "x": PAGE["x"],
        "y": PAGE["band_y"] + drop,
        "w": PAGE["width"],
        "h": LABEL_ROW + ACTION_LANE + 2 * ACTION_MARGIN + PAD,
    }
    inner = frame["h"] - LABEL_ROW - PAD
    half_inner, lane_half = inner // 2, inner // 2 - ACTION_MARGIN
    cx, cy = frame["x"], frame["y"] + LABEL_ROW + inner // 2
    reach = r_max + note_w + PAD
    if reach > frame["w"]:
        raise DeclarationError(
            f"the action lens needs {reach} px for {hops} rings and their notes; the frame is {frame['w']} wide: fewer rings, or shorter calls"
        )
    if lane_half < max(radius, ah // 2) + 10:
        raise DeclarationError(f"the centre lane of {2 * lane_half} px cannot hold the cause and the action; pin a taller frame in layout:")
    cells.append(cell("frame", html.escape(content["title"], quote=False), BAND, frame["x"], frame["y"], frame["w"], frame["h"]))
    label = f"<b>{html.escape(content['cause']['label'], quote=False)}</b>"
    cells.append(cell("cause", label, lib["cause"]["style"], frame["x"], cy - radius, radius, 2 * radius))
    ax, ay = cx + radius + ACTION_CLEARANCE, cy - ah // 2
    printed = lambda lines: "<br>".join(html.escape(line, quote=False) for line in lines)
    if site:
        cells.append(cell("action", f"<b>{lib['callsite']['phrase']}</b>", lib["callsite"]["style"], ax, ay, aw, ah))
        y = ay + 30
        for n, lines in enumerate(wrapped):
            cells.append(cell(f"action-{n + 1}", printed(lines), member["style"], ax + 14, y, aw - 28, row_h[n], "action"))
            y += row_h[n] + 10
    else:
        cells.append(cell("action", printed(wrapped[0]), lib["action"]["style"], ax, ay, aw, ah))
    tag, flow, mark = lib["effect"]["tag"], LIB["edges"]["flow"]["style"], LIB["marks"]["marker"]
    labelled = flow.replace("shadow=0;", "fontColor=@ink;fontStyle=1;fontSize=11;labelBackgroundColor=@band;shadow=0;")
    box_of = {"cause": {"x": frame["x"], "y": cy - radius, "w": radius, "h": 2 * radius}, "action": {"x": ax, "y": ay, "w": aw, "h": ah}}
    zone_of = {"cause": 0, "action": 0}
    # The story's numbers, one per box: the cause, the action, then every effect in its order.
    numbered = [("cause", (cx + 4, cy - radius - 11)), ("action", marker_xy({"x": ax, "y": ay, "w": aw, "h": ah}, "top-left"))]
    for k in range(1, hops + 1):
        r_in, r = r0 + (k - 1) * gap, r0 + k * gap
        # A ring is a perfect circle centred on the cause's rim, drawn only where it crosses the frame's inner height: an arc from the
        # inner top boundary to the inner bottom one, mirrored on the centre line, and steeper the further out it stands.
        turn = math.asin(min(1.0, half_inner / r)) / (2 * math.pi)
        style = re.sub(r"(start|end)Angle=[^;]*;", "", lib["ring"]["style"]) + f"startAngle={1 - turn:.4f};endAngle={turn:.4f};"
        cells.append(cell(f"ring-{k}", "", style, cx - r, cy - r, 2 * r, 2 * r))
        # A zone is what lies inside a ring's line and outside the one before it; its effects stand in the lane, spread evenly top to
        # bottom in the story's order, each centred on the zone's middle curve.
        in_zone = [e for e in effects if e["zone"] == k]
        heights = [note_h(e) for e in in_zone]
        if sum(heights) + 24 * (len(in_zone) - 1) > 2 * lane_half:
            raise DeclarationError(
                f"zone {k} holds {len(in_zone)} effects of {sum(heights)} px, more than the centre lane of {2 * lane_half} px; "
                "move one to the next zone, or pin a taller frame in layout:"
            )
        # A zone narrows towards the lane's top and bottom, where its rings curve in; a note stands just right of the zone's inner
        # curve and must end before its outer one, so the notes spread as far as the zone lets them, towards the centre line otherwise.
        inner = (lambda y: r0 - ACTION_CLEARANCE / 2) if k == 1 else (lambda y: math.sqrt(max(0.0, r_in**2 - y**2)))
        outer = lambda y: math.sqrt(max(0.0, r**2 - y**2))
        full_step = (2 * lane_half - sum(heights)) / (len(in_zone) + 1)

        def tops_at(scale):  # the notes' top edges, relative to the centre line: 1 spreads them over the lane, 0 packs them at it
            step = 24 + (full_step - 24) * scale
            top, tops = -(sum(heights) + step * (len(in_zone) - 1)) / 2, []
            for h in heights:
                tops.append(top)
                top += h + step
            return tops

        def fitted(tops):  # each note's left edge, or None when one note does not fit between its zone's curves
            boxes = []
            for top, h in zip(tops, heights):
                near = 0.0 if top <= 0 <= top + h else min(abs(top), abs(top + h))
                left = inner(near) + 12
                if left + note_w > outer(max(abs(top), abs(top + h))) - 12:
                    return None
                boxes.append(left)
            return boxes

        best = fitted(tops_at(0.0))
        if best is None:
            raise DeclarationError(f"zone {k} cannot hold its {len(in_zone)} effects between its rings; move one to the next zone, or fewer words")
        low, high = 0.0, 1.0
        for _ in range(16):
            mid = (low + high) / 2
            boxes = fitted(tops_at(mid))
            if boxes is None:
                high = mid
            else:
                low, best = mid, boxes
        for e, h, left, top in zip(in_zone, heights, best, tops_at(low)):
            x, y = round(cx + left), round(cy + top)
            said, line = note_lines(e)
            says = f"<b>{html.escape(e['says'], quote=False)}</b>" if said else ""
            text = says + ("<br>" if said and line else "") + printed(line)
            style = member["style"] if "call" in e else lib["effect"]["style"]  # an execution is drawn as a command row, a state as a note
            cells.append(cell(e["id"], text, style, x, y, note_w, h))
            if "where" in e:  # a chip only where the effect's where differs from the diagram's
                cells.append(
                    cell(f"{e['id']}-tag", e["where"], tag["style"], x + note_w - tag["size"][0] - 8, y - 8, tag["size"][0], tag["size"][1])
                )
            source = e.get("after", "action")
            box_of[e["id"]] = {"x": x, "y": y, "w": note_w, "h": h}
            zone_of[e["id"]] = k
            skip = (cy, lane_half, ACTION_MARGIN) if k - zone_of[source] > 1 else None  # a zone skipped: the margin carries the edge
            cells.append(operator_edge(f"e-{source}-{e['id']}", operator(source, e), labelled, source, e["id"], box_of, skip))
            numbered.append((e["id"], marker_xy({"x": x, "y": y, "w": note_w, "h": h}, "top-left")))
    # The cause reaches its action through cats, always: the edge says so, and the cause's own words never need to.
    cells.append(operator_edge("e-cause-action", "cats", labelled, "cause", "action", box_of))
    for n, (_, (mx, my)) in enumerate(numbered, 1):
        cells.append(cell(f"mark-{n}", str(n), mark["style"], round(mx), round(my), mark["size"][0], mark["size"][1]))
    bottom = frame["y"] + frame["h"]
    if content.get("proof", "shown" if PROOF_SHOWN else "hidden") == "shown":  # the Proof box under the frame, as wide as it
        bottom = proof_cells(cells, content["action"], frame["x"], bottom + GAP, frame["w"])
    return finish(cells, content, bottom, declaration)


def engine_words(call, idiom):
    """A contract-form call in the words an engine runs it as: `pascal` is PowerShell's Verb-Noun with -Parameter 'value', `kebab` the
    POSIX shells' kebab-case command with --parameter 'value'. A true switch stands alone, a false one says so, a number stays bare."""
    ((name, args),) = call.items()
    words = name.split("_")
    if idiom == "pascal":
        head = words[0].capitalize() + ("-" + "".join(w.capitalize() for w in words[1:]) if len(words) > 1 else "")
        parts = [head]
        for key, value in args.items():
            parameter = "-" + "".join(w.capitalize() for w in key.split("_"))
            parts.append(parameter if value is True else f"{parameter}:$false" if value is False else f"{parameter} '{value}'" if isinstance(value, str) else f"{parameter} {value}")
    else:
        parts = [name.replace("_", "-")]
        for key, value in args.items():
            parameter = "--" + key.replace("_", "-")
            parts.append(parameter if value is True else f"{parameter} false" if value is False else f"{parameter} '{value}'" if isinstance(value, str) else f"{parameter} {value}")
    return " ".join(parts)


def proof_cells(cells, action, x, y, w):
    """The Proof box: captioned Proof, as wide as the frame it stands under, holding for each call of the action its normalized statement,
    the one line cats knows, and under it the words each engine runs that statement as. Returns the box's bottom."""
    calls = action["calls"] if "calls" in action else [action["call"]]
    h = LABEL_ROW + len(calls) * (1 + len(PROOF_ENGINES)) * PROOF_ROW + (len(calls) - 1) * 10 + PAD
    cells.append(cell("proof", "Proof", BAND, x, y, w, h))
    bright = TEXT.replace("fontColor=@quiet", "fontColor=@ink")
    row_y = y + LABEL_ROW - 6
    for n, call in enumerate(calls, 1):
        line = html.escape(call_line(call), quote=False)
        cells.append(cell(f"proof-{n}-cats", f"<b>cats</b>&nbsp;&nbsp;{line}", bright, x + PAD, row_y, w - 2 * PAD, PROOF_ROW))
        row_y += PROOF_ROW
        for engine, idiom in PROOF_ENGINES:
            words = html.escape(engine_words(call, idiom), quote=False)
            cells.append(cell(f"proof-{n}-{engine}", f"<b>{engine}</b>&nbsp;&nbsp;{words}", TEXT, x + PAD, row_y, w - 2 * PAD, PROOF_ROW))
            row_y += PROOF_ROW
        row_y += 10
    return y + h


def operator_edge(cid, word, style, source, target, box_of, skip=None):
    """An operator's edge, drawn from chosen points: it leaves the source's right side at the height nearest its target (a cause at
    its round's apex) and enters the target's left side at the height nearest its source, each clamped inside the middle half of the
    box; its word sits a quarter of the way along, above the line when the edge climbs or runs level, below it when the edge falls.
    An edge that skips a zone (`skip` is the lane's centre line and half-height, and the margin's height) runs through the margin
    instead of behind the notes it passes: up or down beside its source, across the margin, and down or up into its target, with its
    word on the run across."""
    a, b = box_of[source], box_of[target]
    a_mid, b_mid = a["y"] + a["h"] / 2, b["y"] + b["h"] / 2
    clamp = lambda t: round(min(0.75, max(0.25, t)), 2)
    if skip:
        cy, lane_half, margin = skip
        above = b_mid <= cy
        run = cy - lane_half - margin / 2 if above else cy + lane_half + margin / 2
        edge = edge_cell(cid, f"<b>{word}</b>", style + "exitX=1;exitY=0.5;entryX=0;entryY=0.5;", source, target)
        edge["via"] = [[round(a["x"] + a["w"] + 20), round(run)], [round(b["x"] - 20), round(run)]]
        edge["label_at"] = (0, -12 if above else 12)
        return edge
    exit_y = 0.5 if source == "cause" else clamp((b_mid - a["y"]) / a["h"])
    entry_y = clamp((a_mid - b["y"]) / b["h"])
    edge = edge_cell(cid, f"<b>{word}</b>", style + f"exitX=1;exitY={exit_y};entryX=0;entryY={entry_y};", source, target)
    edge["label_at"] = (-0.5, 12 if b_mid > a_mid else -12)  # a level edge reads like a climbing one: the word above
    return edge


def legend_box(cells, cid, caption, entries, x, y, w):
    """One box of the one-legend band: captioned in its upper-left inside corner, its entries in three rows of columns; each swatch is
    centred in a left column of the box's widest swatch, and its words stand left-aligned in the next column. Returns the box's
    height, before the box is drawn to the band's common height by the caller."""
    rows = 3
    columns = max(1, (len(entries) + rows - 1) // rows)
    col_w = min(240, (w - 32) // columns)
    placed = []  # (eid, swatch cells at the origin, bounding box, phrase)
    for eid, swatch, phrase in entries:
        drawn = swatch(eid, 0, 0)
        boxes = [c for c in drawn if not c["edge"]]
        x0, y0 = min(c["x"] for c in boxes), min(c["y"] for c in boxes)
        x1, y1 = max(c["x"] + c["w"] for c in boxes), max(c["y"] + c["h"] for c in boxes)
        placed.append((eid, drawn, (x0, y0, x1 - x0, y1 - y0), phrase))
    swatch_col = max([b[2] for _, _, b, _ in placed] + [40]) + 8
    for i, (eid, drawn, (x0, y0, bw, bh), phrase) in enumerate(placed):
        col, row = divmod(i, rows)
        sx, sy = x + 16 + col * col_w, y + 30 + row * 28
        dx, dy = sx + (swatch_col - bw) / 2 - x0, sy + 10 - bh / 2 - y0  # the swatch centred in its column and on its row
        for c in drawn:
            if not c["edge"]:
                c["x"], c["y"] = round(c["x"] + dx), round(c["y"] + dy)
        cells.extend(drawn)
        cells.append(cell(f"lg-{eid}-t", brief(phrase), TEXT, sx + swatch_col + 8, sy - 1, col_w - swatch_col - 16, 20))
    return 30 + rows * 28 if entries else 48


def finish(cells, content, content_bottom, declaration):
    """The one-legend band under the drawing: one box per segment standing above it, each as wide as its segment and captioned in its
    upper-left inside corner, the map key under the sidebar in the same band; then the sidebar, and every cell in paint order with the
    page height. The band never rises above the sidebar's minimaps, so a short drawing leaves room under itself instead."""
    legend_y = max(content_bottom, SIDEBAR[-1][1] + SIDEBAR[-1][2]) + GAP
    entries = legend_entries(content)
    # The rule key: every rule a chip names, by its number in about.adrs, three to a column under the entries.
    keyed = [r for r in content["adrs"] if any(c["kind"] == "rule" and c["rule"] == r for c in content["chips"])]
    key_rows = (len(keyed) + 2) // 3
    boxes = []  # (cell id, caption, entries, x, w)
    if content["lens"] == ACTION_LENS and any(eid == "proof" for eid, _, _ in entries):
        proof_w = 320
        boxes.append(("legend", "Action", [e for e in entries if e[0] != "proof"], PAGE["x"], PAGE["width"] - proof_w - GAP))
        boxes.append(("legend-proof", "Proof", [e for e in entries if e[0] == "proof"], PAGE["x"] + PAGE["width"] - proof_w, proof_w))
    else:
        boxes.append(("legend", "Proof" if content["lens"] == PROOF_LENS else "Legend", entries, PAGE["x"], PAGE["width"]))
    heights = []
    for cid, caption, box_entries, bx, bw in boxes:
        heights.append(legend_box(cells, cid, caption, box_entries, bx, legend_y, bw) + (key_rows * 16 + 8 if keyed and cid == "legend" else 0))
    band_h = max(heights + [82])
    for (cid, caption, _, bx, bw), _ in zip(boxes, heights):
        cells.append(cell(cid, f"<b>{caption}</b>", LEGEND, bx, legend_y, bw, band_h))
    for i, rule in enumerate(keyed):
        col, row = divmod(i, key_rows)
        number = content["adrs"].index(rule) + 1
        cells.append(cell(f"lg-key-{number}", f"#{number}  {rule}", KEY, PAGE["x"] + 16 + col * 410, legend_y + 30 + 3 * 28 + row * 16, 400, 16))
    # The map key, the two marks every minimap shares, stands in the same band under the sidebar.
    cells.append(cell("mapkey", "<b>Map key</b>", LEGEND, SIDEBAR_X, legend_y, SIDEBAR_W, band_h))
    for i, (swatch, phrase) in enumerate((("@map-lit", "lit: what this diagram draws"), ("@map-panel", "dim: what sits around it"))):
        y = legend_y + 30 + i * 28
        rim = "none" if swatch == "@map-lit" else "@map-rim"
        cells.append(cell(f"mk-{i}", "", f"rounded=1;arcSize=20;html=1;fillColor={swatch};strokeColor={rim};shadow=0;", SIDEBAR_X + 23, y + 2, 26, 16))
        cells.append(cell(f"mk-{i}-t", phrase, TEXT, SIDEBAR_X + 64, y - 1, SIDEBAR_W - 72, 20))
    # The sidebar: the three minimaps, drawn from their claims and embedded, and the lens badge. The ADR codes live in the subtitle
    # alone.
    height = max(PAGE["min_height"], legend_y + band_h + GAP, SIDEBAR[-1][1] + SIDEBAR[-1][2] + GAP)
    cells.insert(0, cell("sidebar-bg", "", SIDEBAR_BG, SIDEBAR_X - 12, 4, SIDEBAR_W + 24, height - 8))
    # Each minimap is drawn from the data Catzc.Base.Maps computed for the folder (with_data); a declaration put without its folder
    # draws the declared minimaps empty.
    data = declaration.get("minimap_data") or {}
    for (cid, y, h), minimap in zip(SIDEBAR, list(data) or shown_minimaps(content["minimaps"])):
        drawn = data.get(minimap) or {"id": minimap, "axes": [], "cells": [], "lit": []}
        image = minimaps.picture_from(drawn, SIDEBAR_W, h, content["theme"])
        cells.append(cell(cid, minimap, MINIMAP + f"noLabel=1;image={image};", SIDEBAR_X, y, SIDEBAR_W, h))
    return in_paint_order(cells), height


def legend_entries(content):
    """What the legend shows: the glyph kinds, edge kinds and marks the diagram uses, or the phrases the declaration lists."""
    glyphs = LIB["glyphs"]

    def swatch_for(kind):
        style = glyphs[kind]["style"]
        shape = style_map(style).get("shape", "")
        size = {"note": (32, 22), "cylinder3": (28, 26), "hexagon": (40, 22), "delay": (14, 22)}.get(
            shape, (24, 22) if "ellipse" in style else (36, 26) if "rhombus" in style else (40, 18)
        )
        swatch_style = ";".join(
            p
            for p in style.split(";")
            if p and not p.startswith(("whiteSpace", "fontColor", "fontSize", "fontStyle", "boundedLbl", "backgroundOutline", "perimeter"))
        )
        swatch_style = swatch_style.replace("size=14", "size=6").replace("size=8", "size=4") + ";"
        return lambda eid, x, y: [cell(f"lg-{eid}", "", swatch_style, x, y, size[0], size[1])]

    def edge_swatch(kind):
        style = LIB["edges"][kind]["style"]
        return lambda eid, x, y: [
            cell(f"lg-{eid}-a", "", ANCHOR, x, y + 9, 1, 1),
            cell(f"lg-{eid}-b", "", ANCHOR, x + 40, y + 9, 1, 1),
            edge_cell(f"lg-{eid}", "", style, f"lg-{eid}-a", f"lg-{eid}-b"),
        ]

    def mark_swatch(kind, text):
        mark = LIB["marks"][kind]
        return lambda eid, x, y: [cell(f"lg-{eid}", text, mark["style"], x + 4, y - 2, mark["size"][0], mark["size"][1])]

    entries = []
    wanted = content["legend"] if isinstance(content["legend"], list) else None
    proof_box = "rounded=1;arcSize=6;html=1;fillColor=@band;strokeColor=@line;shadow=0;"  # the Proof box, small and rimmed to show
    proof_swatch = lambda eid, x, y: [cell(f"lg-{eid}", "", proof_box, x, y + 2, 40, 18)]
    if content["lens"] == PROOF_LENS:  # the statement's glyph and the Proof box
        entries.append(("callsite" if "calls" in content["action"] else "action", swatch_for("action"), glyphs["action"]["phrase"]))
        entries.append(("proof", proof_swatch, "proof: the statement in each engine's words"))
    if content["lens"] == ACTION_LENS:  # the lens's own kinds, its four operators, the story's numbers and its Proof box
        for kind in ("cause", "callsite" if "calls" in content["action"] else "action", "ring", "effect"):
            entries.append((kind, swatch_for(kind), glyphs[kind]["phrase"]))
        if content.get("proof", "shown" if PROOF_SHOWN else "hidden") == "shown":
            entries.append(("proof", proof_swatch, "proof: the statement in each engine's words"))
        if any("call" in e for e in content["effects"]):
            member = glyphs["callsite"]["member"]
            swatch = lambda eid, x, y: [cell(f"lg-{eid}", "", member["style"], x, y + 2, 40, 18)]
            entries.append(("execution", swatch, "execution: a triggered command"))
        drawn_words = {"cats", "executes"} | {
            "affects" if "call" in e else "effects" for e in content["effects"] if e.get("after", "action") != "action"
        }
        for word, meaning in OPERATORS.items():
            if content["legend"] != "used" or word in drawn_words:  # legend: used lists the operators the drawing draws
                entries.append((f"edge-{word}", edge_swatch("flow"), f"{word}: {meaning}"))
        entries.append(("marker", mark_swatch("marker", "1"), LIB["marks"]["marker"]["phrase"]))
    for kind in dict.fromkeys(g["kind"] for g in content["glyphs"]):
        if kind != "commit":
            entries.append((kind, swatch_for(kind), glyphs[kind]["phrase"]))
            continue
        # Commits: one entry per palette state the diagram draws, and one entry for a ghost of any state.
        commits = [g for g in content["glyphs"] if g["kind"] == "commit"]
        for state in dict.fromkeys(g.get("state", COMMIT_STATES[0]) for g in commits):
            style = commit_style(glyphs["commit"]["style"], state, False)
            swatch = lambda eid, x, y, style=style: [cell(f"lg-{eid}", "", style, x + 8, y - 2, 22, 22)]
            entries.append((f"commit-{state}", swatch, f"commit: {state}"))
        ghosts = [g for g in commits if g.get("ghost", False)]
        if ghosts:
            style = commit_style(glyphs["commit"]["style"], ghosts[0].get("state", COMMIT_STATES[0]), True)
            swatch = lambda eid, x, y, style=style: [cell(f"lg-{eid}", "", style, x + 8, y - 2, 22, 22)]
            entries.append(("commit-ghost", swatch, "commit: ghost"))
    for kind in dict.fromkeys(e["kind"] for e in content["edges"]):
        phrase = (
            f"flow: {content['relation']}"
            if kind == "flow" and content["relation"]
            else content["thick"]
            if kind == "thick" and content.get("thick")
            else LIB["edges"][kind]["phrase"]
        )
        entries.append((f"edge-{kind}", edge_swatch(kind), phrase))
    for kind in dict.fromkeys(r["kind"] for r in content.get("rules") or []):  # a gate rule's line, solid or dashed
        swatch = lambda eid, x, y, style=RULE_STYLES[kind]: [
            cell(f"lg-{eid}-a", "", ANCHOR, x, y + 9, 1, 1),
            cell(f"lg-{eid}-b", "", ANCHOR, x + 40, y + 9, 1, 1),
            edge_cell(f"lg-{eid}", "", style, f"lg-{eid}-a", f"lg-{eid}-b"),
        ]
        entries.append((f"rule-{kind}", swatch, f"{kind} gate"))
    if content["markers"]:
        entries.append(("marker", mark_swatch("marker", "1"), LIB["marks"]["marker"]["phrase"]))
    for kind in dict.fromkeys(c["kind"] for c in content["chips"]):
        entries.append((f"chip-{kind}", mark_swatch(kind, "#2" if kind == "rule" else "87"), LIB["marks"][kind]["phrase"]))
    if any(c["kind"] == "rule" and not c.get("gated", True) for c in content["chips"]):
        mark = LIB["marks"]["rule"]
        dashed = lambda eid, x, y: [cell(f"lg-{eid}", "#2", mark["style"] + "dashed=1;", x + 4, y - 2, mark["size"][0], mark["size"][1])]
        entries.append(("chip-rule-adr", dashed, "dashed rule chip: DRS-only (no gate)"))
    if wanted is not None:
        entries = [e for e in entries if e[2] in wanted]
    return entries


def to_xml(cells, height, theme=None):
    """The mxGraphModel text, one cell a line, in the kit's fixed formatting so the same cells give the same bytes; every style token
    is written as the theme's colour."""
    lines = [
        f'<mxGraphModel dx="1024" dy="768" grid="0" gridSize="10" guides="1" tooltips="1" connect="1" arrows="1" fold="1" page="1" pageScale="1" pageWidth="1572" pageHeight="{height}" background="{paint("@page", theme)}" math="0" shadow="1">',
        "  <root>",
        '    <mxCell id="0" />',
        '    <mxCell id="1" parent="0" />',
    ]
    origin = {c["id"]: (c["x"], c["y"]) for c in cells if not c["edge"]}
    for c in cells:
        value = html.escape(c["value"], quote=True)
        if c["edge"]:
            lines.append(
                f'    <mxCell id="{c["id"]}" value="{value}" style="{paint(c["style"], theme)}" edge="1" parent="{c["parent"]}" source="{c["source"]}" target="{c["target"]}">'
            )
            # A label placed by the kit sits at a fraction along the edge (-1 the source, 1 the target) and a perpendicular offset in px,
            # positive below a rightward edge, as draw.io reads an edge label's relative geometry.
            at = f' x="{c["label_at"][0]}" y="{c["label_at"][1]}"' if c.get("label_at") else ""
            if c.get("via"):
                px, py = origin.get(c["parent"], (0, 0))  # an edge inside a container takes its waypoints relative to it
                lines.append(f'      <mxGeometry{at} relative="1" as="geometry">')
                lines.append('        <Array as="points">')
                lines.extend(f'          <mxPoint x="{x - px}" y="{y - py}" />' for x, y in c["via"])
                lines.append("        </Array>")
                lines.append("      </mxGeometry>")
            else:
                lines.append(f'      <mxGeometry{at} relative="1" as="geometry" />')
        else:
            px, py = origin.get(c["parent"], (0, 0)) if c["parent"] != "1" else (0, 0)
            lines.append(
                f'    <mxCell id="{c["id"]}" value="{value}" style="{paint(c["style"], theme)}" vertex="1" parent="{c["parent"]}">'
            )
            lines.append(f'      <mxGeometry x="{c["x"] - px}" y="{c["y"] - py}" width="{c["w"]}" height="{c["h"]}" as="geometry" />')
        lines.append("    </mxCell>")
    lines.extend(["  </root>", "</mxGraphModel>"])
    return "\n".join(lines) + "\n"


def put(declaration, theme=None):
    """The model XML of a declaration, in the theme named (the declaration's own theme when none is)."""
    theme = theme or declaration["content"]["theme"]
    cells, height = place({**declaration, "content": {**declaration["content"], "theme": theme}})
    return to_xml(cells, height, theme)


def put_png(folder, declaration, theme=None):
    """put, then the raster: the diagram's <name>.drawio.png with the model embedded, drawn by drawio_png. The default theme's
    render is the diagram's own png; any other theme renders on demand to out/drawio/themes/<theme>/<name>.drawio.png."""
    theme = theme or declaration["content"]["theme"]
    model = put(with_data(folder, declaration), theme).strip()
    img = render(ET.fromstring(model), page="model").convert("RGB")  # the model's own page: its theme's
    info = PngInfo()
    info.add_text("mxfile", encode(model, declaration["content"]["lens"]))
    dst = slide_of(folder) if theme == THEMES[0] else KIT.parents[1] / "out" / "drawio" / "themes" / theme / slide_of(folder).name
    dst.parent.mkdir(parents=True, exist_ok=True)
    img.save(dst, "PNG", pnginfo=info)
    return dst


# ---- get: the model becomes the declaration ------------------------------------------------------------------------


def signature(style):
    s = style_map(paint(style))  # the library's tokens in the default theme, the one a committed drawing is put in
    return tuple((k, s.get(k)) for k in SIGNATURE_KEYS if k in s)


def matches(sig, style):
    s = style_map(style)
    return all(s.get(k) == v for k, v in sig)


def model_of(folder):
    """The model embedded in the diagram's <name>.drawio.png."""
    return decode(mxfile_chunk(Image.open(slide_of(folder)))).strip()


def shift_of(title_style):
    """How far span room moved a drawing area down, from its title's style: 0 when it did not move."""
    return int(style_map(title_style or "").get(SHIFT_KEY, 0))


def get(model, kind=None):
    """The declaration a model states, in the kit's vocabulary; a cell the vocabulary cannot name fails the direction."""
    root = ET.fromstring(model)
    cells = {str(c.get("id")): c for c in root.iter("mxCell") if c.get("id") not in (None, "0", "1")}
    shift = shift_of(cells["title"].get("style")) if "title" in cells else 0
    declared = lambda box: {**box, "y": box["y"] - shift}  # a layout box as the yml declares it, before span room moved it
    geo = {}
    for cid, c in cells.items():
        g = c.find("mxGeometry")
        if c.get("edge") == "1" or g is None:
            continue
        x, y = float(g.get("x", 0)), float(g.get("y", 0))
        parent = cells.get(c.get("parent") or "")
        while parent is not None:
            pg = parent.find("mxGeometry")
            if pg is None:
                break
            x, y = x + float(pg.get("x", 0)), y + float(pg.get("y", 0))
            parent = cells.get(parent.get("parent") or "")
        geo[cid] = {"x": int(x), "y": int(y), "w": int(float(g.get("width", 0))), "h": int(float(g.get("height", 0)))}
    glyph_sigs = {k: signature(v["style"]) for k, v in LIB["glyphs"].items()}
    if "lens-badge" in cells and plain(cells["lens-badge"].get("value")).lower() == PROOF_LENS:
        return get_proof(cells, kind)
    if any(matches(glyph_sigs["cause"], c.get("style") or "") for cid, c in cells.items() if not cid.startswith("lg-")):
        return get_action(cells, geo, glyph_sigs, kind)
    palette_fills = {fill.upper(): state for state, (fill, _, _) in COMMITS.items()}
    mark_sigs = {k: signature(v["style"]) for k, v in LIB["marks"].items()}
    module_sig = signature(LIB["module"])
    content: dict = {"title": "", "kind": kind or KINDS[0], "flow": FLOWS[0]}
    lens = "meta"
    adrs: list = []
    content.update({"theme": next(iter(DEFAULTS["themes"])), "bands": [], "spans": [], "groups": [], "glyphs": []})
    content.update({"edges": [], "markers": [], "chips": [], "legend": "auto"})
    # The drawing carries each minimap's view, not what its author excludes: save() keeps the source's entries.
    content["minimaps"] = [plain(cells[cid].get("value")) for cid, _, _ in SIDEBAR if cid in cells]
    flow_phrase = plain(cells["lg-edge-flow-t"].get("value")) if "lg-edge-flow-t" in cells else ""
    content["relation"] = flow_phrase[len("flow: ") :] if flow_phrase.startswith("flow: ") else ""
    thick_phrase = plain(cells["lg-edge-thick-t"].get("value")) if "lg-edge-thick-t" in cells else ""
    content["thick"] = thick_phrase if thick_phrase and thick_phrase != brief(LIB["edges"]["thick"]["phrase"]) else ""
    layout = {}
    unnamed = []
    bands, groups, glyphs, bars, labels, markers, chips, notes = [], [], [], [], [], [], [], []
    lens = plain(cells["lens-badge"].get("value")).lower() if "lens-badge" in cells else lens
    for cid, c in cells.items():
        style, value = c.get("style") or "", plain(c.get("value"))
        if c.get("edge") == "1" or cid in DERIVED or cid.startswith(DERIVED_PREFIXES) or cid.endswith("-tag"):
            continue
        if cid == "title":
            content["title"] = value
        elif cid == "subtitle":
            adrs = [p.strip() for p in value.split("·") if p.strip()]
        elif style_map(style).get("noteBlock") == "1":
            notes.append(cid)
        elif matches(signature(BAND), style):
            bands.append(cid)
        elif matches(module_sig, style):
            groups.append(cid)
        elif style_map(style).get("shape") == "crossbar":
            bars.append(cid)
        elif matches(signature(SPAN_LABEL), style):
            labels.append(cid)
        elif matches(mark_sigs["marker"], style) and value.isdigit():
            markers.append(cid)
        elif matches(mark_sigs["rule"], style) or matches(mark_sigs["count"], style):
            chips.append(cid)
        elif ("ellipse" in style_map(style) or style_map(style).get("commitShape") == "box") and style_map(style).get(
            "fillColor", ""
        ).upper() in palette_fills:
            glyphs.append((cid, "commit"))  # a commit in any palette state, a dot or a box
        else:
            kinds = [k for k, sig in sorted(glyph_sigs.items(), key=lambda kv: -len(kv[1])) if matches(sig, style)]
            if f"{cid}-tag" in cells and "type" in kinds:
                glyphs.append((cid, "type"))
            elif kinds:
                glyphs.append((cid, kinds[0]))
            else:
                unnamed.append(cid)
    if unnamed:
        raise DeclarationError(f"get cannot name these cells in the kit's vocabulary: {', '.join(unnamed)}")
    inside = lambda inner, outer: (
        outer["x"] <= inner["x"] + inner["w"] / 2 <= outer["x"] + outer["w"]
        and outer["y"] <= inner["y"] + inner["h"] / 2 <= outer["y"] + outer["h"]
    )
    bands.sort(key=lambda b: (geo[b]["y"], geo[b]["x"]))
    for b in bands:
        content["bands"].append({"id": b, "label": plain(cells[b].get("value"))})
        layout[b] = declared(geo[b])
    if len(bands) > 1 and all(geo[b]["x"] == geo[bands[0]]["x"] for b in bands):
        content["flow"] = "top-to-bottom"

    envs = {g for g, k in glyphs if k == "env"}

    def holder_of(cid):
        parent = cells[cid].get("parent")
        if parent in groups or parent in envs:  # a frame, or the environment a commit occupies
            return parent
        candidates = [b for b in bands if inside(geo[cid], geo[b])]
        return candidates[0] if candidates else (bands[0] if bands else None)

    # Groups and glyphs come holder by holder, depth first (a band, then the groups inside it, each with the groups inside it),
    # row-major inside each holder.
    holders = {h: holder_of(h) for h in groups}
    order = []

    def walk(holder_id):
        order.append(holder_id)
        for g in sorted((g for g in groups if holders[g] == holder_id), key=lambda g: (geo[g]["y"], geo[g]["x"])):
            walk(g)

    for b in bands:
        walk(b)
    rank = {h: i for i, h in enumerate(order)}
    for g in sorted(groups, key=lambda g: (rank[holders[g]], geo[g]["y"], geo[g]["x"])):
        content["groups"].append({"id": g, "label": plain(cells[g].get("value")) or " ", "in": holders[g]})  # " ": an untitled frame
        layout[g] = declared(geo[g])

    def reading_order(t):  # holder by holder, row-major; an environment's occupants come after the glyphs of the environment's holder
        h = holder_of(t[0])
        return (rank[holder_of(h)], 1, geo[t[0]]["y"], geo[t[0]]["x"]) if h in envs else (rank[h], 0, geo[t[0]]["y"], geo[t[0]]["x"])

    for cid, k in sorted(glyphs, key=reading_order):
        glyph = {"id": cid, "kind": k, "label": plain(cells[cid].get("value")), "in": holder_of(cid)}
        if k == "commit":
            s = style_map(cells[cid].get("style"))
            if s.get("commitShape") == "box":
                glyph["shape"] = "box"
            state = palette_fills[s.get("fillColor", "").upper()]
            if state != COMMIT_STATES[0]:
                glyph["state"] = state
            if s.get("dashed") == "1":
                glyph["ghost"] = True
        content["glyphs"].append(glyph)
        layout[cid] = declared(geo[cid])
    content["notes"] = []
    for cid in sorted(notes, key=lambda n: (rank[holder_of(n)], geo[n]["y"], geo[n]["x"])):
        content["notes"].append({"id": cid, "in": holder_of(cid), "text": plain(cells[cid].get("value"))})
        layout[cid] = declared(geo[cid])
    for bar in bars:
        box = geo[bar]
        vertical = "rotation=90" in (cells[bar].get("style") or "")
        near = [
            l
            for l in labels
            if abs((geo[l]["x"] + geo[l]["w"] / 2) - (box["x"] + box["w"] / 2)) <= 40
            and abs((geo[l]["y"] + geo[l]["h"] / 2) - (box["y"] + box["h"] / 2)) <= (box["h"] / 2 + 40 if vertical else 40)
        ]
        if vertical:
            over = [b for b in bands if geo[b]["y"] >= box["y"] - 2 and geo[b]["y"] + geo[b]["h"] <= box["y"] + box["h"] + 2]
        else:
            under = lambda i, box=box: geo[i]["x"] >= box["x"] - 2 and geo[i]["x"] + geo[i]["w"] <= box["x"] + box["w"] + 2
            over = [b for b in bands if under(b)]
            if (
                not over
                or min(geo[b]["x"] for b in over) > box["x"] + 2
                or max(geo[b]["x"] + geo[b]["w"] for b in over) < box["x"] + box["w"] - 2
            ):
                # Narrower than whole bands: the glyphs and groups standing directly in the band under the bar, left to right.
                below = [
                    b
                    for b in bands
                    if geo[b]["y"] > box["y"] and geo[b]["x"] < box["x"] + box["w"] and box["x"] < geo[b]["x"] + geo[b]["w"]
                ]
                band = min(below, key=lambda b: geo[b]["y"] - box["y"]) if below else None

                def band_of(item):  # a glyph or group's band, through any frames it sits in
                    h = holders.get(item) if item in groups else holder_of(item)
                    while h in groups:
                        h = holders[h]
                    return h

                members = [m for m in list(groups) + [g for g, _ in glyphs] if band_of(m) == band and under(m)]
                # The outermost covered items: a member whose frame is itself covered is named through that frame.
                over = sorted(
                    (
                        m
                        for m in members
                        if not (m in holders and holders[m] in members) and not (m not in groups and holder_of(m) in members)
                    ),
                    key=lambda m: geo[m]["x"],
                )
        content["spans"].append({"id": bar, "label": plain(cells[near[0]].get("value")) if near else "", "over": over})
    glyph_ids = [g[0] for g in glyphs]
    kind_of = dict(glyphs)

    # Where put centres a marker: a corner of a box (named), beside a diamond's top point or inside a band's or group's top-left
    # corner (the default, no name), or the middle of an edge.
    def anchors(g):
        x, y, w, h = geo[g]["x"], geo[g]["y"], geo[g]["w"], geo[g]["h"]
        corners = [
            ("top-left", (x + 1, y)),
            ("top-right", (x + w - 1, y)),
            ("bottom-left", (x + 1, y + h)),
            ("bottom-right", (x + w - 1, y + h)),
        ]
        if g not in kind_of:
            return [(None, (x + 15, y))] + corners
        return ([(None, (x + w // 2 - 29, y + 7))] if kind_of[g] == "gate" else []) + corners

    edge_ends = [
        (c.get("source"), c.get("target")) for cid, c in cells.items() if c.get("edge") == "1" and not cid.startswith(("lg-", "lane-"))
    ]
    places = [(g, name, point) for g in glyph_ids + groups + bands for name, point in anchors(g)]
    centre_of = lambda i: (geo[i]["x"] + geo[i]["w"] / 2, geo[i]["y"] + geo[i]["h"] / 2)

    def via_of(c):  # an edge's waypoints on the page: relative to its container when it sits in one
        points = c.find("mxGeometry/Array")
        ox, oy = (geo[c.get("parent")]["x"], geo[c.get("parent")]["y"]) if c.get("parent") in geo else (0, 0)
        return [[float(p.get("x", 0)) + ox, float(p.get("y", 0)) + oy] for p in points.findall("mxPoint")] if points is not None else []

    edge_paths = [
        (c.get("source"), c.get("target"), via_of(c))
        for cid, c in cells.items()
        if c.get("edge") == "1" and not cid.startswith(("lg-", "lane-"))
    ]
    places += [(f"{s}->{t}", "edge", edge_middle(geo[s], geo[t], via)) for s, t, via in edge_paths if s in geo and t in geo]
    for m in sorted(markers, key=lambda m: int(plain(cells[m].get("value")))):
        centre = centre_of(m)
        at, name, _ = min(places, key=lambda p: abs(p[2][0] - centre[0]) + abs(p[2][1] - centre[1]))
        marker = {"at": at, "number": int(plain(cells[m].get("value")))}
        if name not in (None, "edge"):
            sources = [geo[s] for s, t in edge_ends if t == at and s in geo]
            if kind_of.get(at) in (None, "gate") or name != auto_corner(geo[at], sources):
                marker["corner"] = name
        content["markers"].append(marker)
    # A chip's id is chip-<kind>-<place>-<n>, so the place it sits on is read from the id, in the order put drew them.
    for ch in chips:
        style = cells[ch].get("style") or ""
        kind = "rule" if matches(mark_sigs["rule"], style) else "count"
        at = ch.removeprefix(f"chip-{kind}-").rsplit("-", 1)[0]
        value = plain(cells[ch].get("value"))
        if kind == "rule":
            chip = {"at": at, "kind": "rule", "rule": adrs[int(value.lstrip("#")) - 1]}
            if style_map(style).get("dashed") == "1":
                chip["gated"] = False
        else:
            chip = {"at": at, "kind": "count", "text": value}
        if at in geo:  # the corner it sits on, named only when it is not the kind's own
            cx, cy = centre_of(ch)
            box, x = geo[at], geo[ch]["x"]
            # A row of chips stands inward from its corner, 34 px a chip, so a chip far along the row still names its row's corner.
            in_row = lambda offset: offset >= 0 and offset % 34 == 0
            right, left = in_row(box["x"] + box["w"] - 30 - x), in_row(x - box["x"] - 4)
            side = (
                "-right"
                if right and not left
                else "-left"
                if left and not right
                else ("-left" if cx < box["x"] + box["w"] / 2 else "-right")
            )
            corner = ("top" if cy < box["y"] + box["h"] / 2 else "bottom") + side
            if corner != CHIP_CORNER[kind]:
                chip["corner"] = corner
        content["chips"].append(chip)
    edge_sigs = {k: signature(v["style"]) for k, v in LIB["edges"].items()}
    for cid, c in cells.items():
        if c.get("edge") != "1" or cid.startswith(("lg-", "lane-")):
            continue
        kinds = [k for k, sig in sorted(edge_sigs.items(), key=lambda kv: -len(kv[1])) if matches(sig, c.get("style") or "")]
        if not kinds:
            raise DeclarationError(f"get cannot name the edge {cid} in the kit's vocabulary")
        edge = {"from": c.get("source"), "to": c.get("target"), "kind": kinds[0], "label": plain(c.get("value"))}
        if via_of(c) and edge["kind"] != "bypass":  # a bypass's route is the kit's, under the dot it skips
            edge["via"] = [[int(x), int(y) - shift] for x, y in via_of(c)]  # the waypoints as declared, before span room
        content["edges"].append(edge)
    declaration = normalise({"about": {"adrs": adrs, "lens": lens}, "content": content, "layout": layout}, where="the drawing")
    # A cell that sits where the grid would put it needs no layout entry: the layout keeps only what a hand moved.
    # A layout entry stays only where put would not place the cell there anyway, given the entries already kept for what holds it:
    # bands first, then frames from the outside in, then what they hold.
    read, held = declaration["layout"], declaration["content"]
    holder = {i["id"]: i["in"] for key in ("groups", "glyphs", "notes") for i in held.get(key) or []}
    frames = {g["id"] for g in held["groups"]}

    def depth(cid):
        d = 0
        while cid in holder:
            cid, d = holder[cid], d + 1
        return d

    deepest = max((depth(g) for g in frames), default=0)
    level = lambda cid: 0 if cid not in holder else depth(cid) if cid in frames else deepest + 1
    kept: dict = {}
    for lv in sorted({level(cid) for cid in read}):
        gridded = place({"content": held, "layout": kept})[0]
        grid_shift = shift_of(next(c["style"] for c in gridded if c["id"] == "title"))  # the grid's own span room, taken off too
        grid = {c["id"]: {"x": c["x"], "y": c["y"] - grid_shift, "w": c["w"], "h": c["h"]} for c in gridded if not c["edge"]}
        kept.update({cid: box for cid, box in read.items() if level(cid) == lv and grid.get(cid) != box})
    declaration["layout"] = {cid: box for cid, box in read.items() if cid in kept}
    return declaration


def cause_read(label, radius):
    """A drawn cause back in the yml: its label, and its size only when the drawn radius names one the label alone would not give."""
    sizes = cause_sizes()
    nearest = min(sizes, key=lambda name: abs(sizes[name] - radius))
    cause = {"label": label}
    if sizes[nearest] != cause_radius(cause):
        cause["size"] = nearest
    return cause


def proof_action(cells):
    """The action a drawing's Proof box states: its cats rows, in order, each the normalized statement after the word cats."""
    rows = sorted((cid for cid in cells if re.fullmatch(r"proof-\d+-cats", cid)), key=lambda cid: int(cid.split("-")[1]))
    calls = [parse_call(plain(cells[cid].get("value")).split(None, 1)[1]) for cid in rows]
    return {"calls": calls} if len(calls) > 1 else {"call": calls[0]}


def get_proof(cells, kind):
    """The proof lens read back: the title and ADR codes from the chrome, and the action from the Proof box's cats rows."""
    value = lambda cid: plain(cells[cid].get("value"))
    if not any(re.fullmatch(r"proof-\d+-cats", cid) for cid in cells):
        raise DeclarationError("get needs the Proof box's cats rows in a proof drawing; none is drawn")
    content = {
        "title": value("title") if "title" in cells else "",
        "kind": kind or KINDS[0],
        "theme": next(iter(DEFAULTS["themes"])),
        "action": proof_action(cells),
        "minimaps": [value(cid) for cid, _, _ in SIDEBAR if cid in cells],
    }
    adrs = [p.strip() for p in value("subtitle").split("·") if p.strip()] if "subtitle" in cells else []
    return normalise({"about": {"adrs": adrs, "lens": PROOF_LENS}, "content": content}, where="the drawing")


def get_action(cells, geo, glyph_sigs, kind):
    """The action lens read back: the title and ADR codes from the chrome, the cause's label, the action's call or its call site's rows,
    and each effect's note with its where chip and its proof line; an effect's ring is read from its distance to the action's centre
    and its order from its angle, top to bottom, so a moved note folds back to a ring and an order, never to coordinates."""
    value = lambda cid: plain(cells[cid].get("value"))
    styled = lambda k: [
        cid for cid, c in cells.items() if not cid.startswith(("lg-", "proof")) and matches(glyph_sigs[k], c.get("style") or "")
    ]
    causes, sites, actions = styled("cause"), styled("callsite"), styled("action")
    if len(causes) != 1 or len(sites) + len(actions) != 1:
        raise DeclarationError("get needs one cause and one action or call site in an action drawing")
    action_id = (sites or actions)[0]
    if sites:
        rows = sorted((cid for cid, c in cells.items() if c.get("parent") == action_id), key=lambda m: geo[m]["y"])
        action = {"calls": [parse_call(value(m)) for m in rows]}
    else:
        action = {"call": parse_call(value(action_id))}
    cause = geo[causes[0]]
    cx, cy = cause["x"], cause["y"] + cause["h"] / 2  # the rings' centre: the cause's flat side on the frame's rim
    # The rings as drawn, each its radii; a note's zone is the first ring its centre lies inside, by the ellipse's own measure.
    rings = sorted(((geo[cid]["w"] / 2, geo[cid]["h"] / 2) for cid in styled("ring")), key=lambda rr: rr[0])
    if not rings:
        raise DeclarationError("get needs the rings of an action drawing; none is drawn")
    # The story's numbers: each marker numbers the box whose top-left corner it sits on; a moved box keeps its number.
    mark_sig = signature(LIB["marks"]["marker"]["style"])
    marks = [(int(value(cid)), geo[cid]) for cid, c in cells.items() if matches(mark_sig, c.get("style") or "") and value(cid).isdigit()]
    number_of = lambda box: min(
        (abs(m["x"] - (box["x"] - 10)) + abs(m["y"] - (box["y"] - 11)), n) for n, m in marks or [(0, {"x": 0, "y": 0})]
    )[1]
    # An effect's direct cause: the source of the edge into it, when that is another effect.
    after_of = {
        c.get("target"): c.get("source")
        for cid, c in cells.items()
        if c.get("edge") == "1" and not cid.startswith("lg-") and c.get("source") not in ("cause", "action")
    }
    # An execution is drawn as a command row outside the call site; a state change as a note. Either prints its bold words first.
    member_sig = signature(LIB["glyphs"]["callsite"]["member"]["style"])
    executions = [
        cid
        for cid, c in cells.items()
        if c.get("parent") == "1" and not cid.startswith(("lg-", "proof")) and matches(member_sig, c.get("style") or "")
    ]
    effects = []
    for cid in styled("effect") + executions:
        b = geo[cid]
        px, py = b["x"] + b["w"] / 2 - cx, b["y"] + b["h"] / 2 - cy
        drawn = cells[cid].get("value") or ""
        head, _, body = drawn.partition("</b>") if drawn.startswith("<b>") else ("", "", drawn)
        says, line = plain(head), plain(body)
        k = next((k for k, (r, ry) in enumerate(rings, 1) if (px / r) ** 2 + (py / ry) ** 2 <= 1), len(rings))
        effect = {"id": cid, "zone": k}
        if f"{cid}-tag" in cells:  # a chip says the effect's where differs from the diagram's; none says it is the diagram's
            effect["where"] = value(f"{cid}-tag")
        if says and not line:
            effect["show"] = "words"
        elif line and not says:
            effect["show"] = "call"
        if says:
            effect["says"] = says
        if line:
            effect["call" if cid in executions else "proves"] = parse_call(line)
        if cid in after_of:
            effect["after"] = after_of[cid]
        effects.append((k, number_of(b), effect))
    content = {
        "title": value("title") if "title" in cells else "",
        "kind": kind or KINDS[0],
        "theme": next(iter(DEFAULTS["themes"])),
        "cause": cause_read(value(causes[0]), geo[causes[0]]["h"] / 2),
        "action": action,
        "effects": [e for _, _, e in sorted(effects, key=lambda t: t[:2])],
        "minimaps": [value(cid) for cid, _, _ in SIDEBAR if cid in cells],
    }
    if ("proof" in cells) != PROOF_SHOWN:  # the Proof box is drawn or not; the key is kept only where it differs from the default
        content["proof"] = "shown" if "proof" in cells else "hidden"
    adrs = [p.strip() for p in value("subtitle").split("·") if p.strip()] if "subtitle" in cells else []
    return normalise({"about": {"adrs": adrs, "lens": ACTION_LENS}, "content": content}, where="the drawing")


def minimap_data(folder):
    """A diagram's three minimaps as Catzc.Base.Maps computed them, in order: out/minimaps/<stem>/minimaps.json names the ids and
    <id>.json holds each, its computed lit cells less the ones the declaration excludes, checked against the minimap contract. Missing
    data fails, naming the commands that write it."""
    folder = diagram_of(folder).resolve()
    repo = KIT.parents[1]
    rel = folder.relative_to(repo).as_posix() if folder.is_relative_to(repo) else folder.name
    root = repo / "out" / "minimaps" / rel
    index = root / "minimaps.json"
    if not index.is_file():
        raise DeclarationError(
            f"{rel}: no minimap data in out/minimaps/{rel}; Build-Diagrams or Test-Diagrams computes it (Write-DiagramMinimapData)"
        )
    return {view: minimap_contract.load_minimap(root / f"{view}.json") for view in json.loads(index.read_text(encoding="utf-8"))}


def minimaps_block(entries, width=None):
    """content.minimaps as the source's text writes it, two spaces in under content: and in the printed form save writes (flow_yaml):
    the shown ids as one flow line when they fit the print width, an entry with an exclude: as its own item. No entries, no lines."""
    if not entries:
        return []
    width = width or print_width()
    return ["  " + line for line in flow_yaml({"minimaps": entries}, width - 2).rstrip("\n").split("\n")]


def declare_minimaps(folder):
    """Write a diagram's minimaps into its source as their inputs only, in the printed form: the shown ids, each with the exclude: its
    author gave it, and never a computed cell. Only that key's lines change: the rest of the text, its generated head and its formatting
    included, is kept as it was read, never re-dumped, which would drop the head and what a row or lane expands to."""
    text, source = read_source(folder)
    placed = normalise(yaml.safe_load(text) or {}, where=str(source))["content"]["minimaps"]
    lines = text.split("\n")
    content = next((i for i, line in enumerate(lines) if line.rstrip() == "content:"), None)
    if content is None:
        raise DeclarationError(f"{source}: no top-level content: block to write the minimaps into")
    # The content block runs to the next top-level line; its minimaps key, when it has one, runs to the next key of the same depth.
    end = next((i for i in range(content + 1, len(lines)) if lines[i] and not lines[i].startswith((" ", "#"))), len(lines))
    while end > content + 1 and not lines[end - 1].strip():
        end -= 1
    start = next((i for i in range(content + 1, end) if lines[i].startswith("  minimaps:")), None)
    if start is None:
        start = stop = end
    else:
        # A list item at the key's own depth (`  - grid`, as yaml.safe_dump writes a list) is still the key's.
        stop = next(
            (
                i
                for i in range(start + 1, end)
                if lines[i].strip() and len(lines[i]) - len(lines[i].lstrip()) <= 2 and not lines[i].startswith("  - ")
            ),
            end,
        )
    return write_source(folder, "\n".join(lines[:start] + minimaps_block(placed) + lines[stop:]))


def reflow(folder):
    """Rewrite a diagram's source in the printed form (flow_yaml at the print width): its generated head and its keys kept as read, rows
    and lanes unexpanded. Nothing is written when the declaration the new text loads differs from the one the old text loads."""
    text, source = read_source(folder)
    lines = text.split("\n")
    body = next((i for i, line in enumerate(lines) if line.strip() and not line.startswith("#")), len(lines))
    head = "\n".join(lines[:body])
    new = (head + "\n" if body else "") + flow_yaml(yaml.safe_load(text) or {}, print_width())
    where = str(source)
    if normalise(yaml.safe_load(new) or {}, where=where) != normalise(yaml.safe_load(text) or {}, where=where):
        raise DeclarationError(f"{source}: the reflowed text loads a different declaration, so nothing was written")
    return write_source(folder, new)


def with_data(folder, declaration):
    """The declaration with its folder's minimap data, which put draws the sidebar from."""
    return {**declaration, "minimap_data": minimap_data(folder)}


def drift(folder):
    """How a folder's png differs from put of its yml: the drawn cells that differ, and apart from them the cells the kit derives and
    get never reads back (the minimaps, the legend, the map key and the sidebar), which change when a registry or the kit changes and
    so are stale rather than drifted. Both empty when the png is what put would write."""
    changed = changed_cells(model_of(folder), put(with_data(folder, load(folder))).strip())
    stale = [i for i in changed if i in DERIVED or i.startswith(DERIVED_PREFIXES)]
    return [i for i in changed if i not in stale], stale


def changed_cells(one, other):
    """The ids of the cells two models draw differently, sorted; empty when the models are the same."""
    if one == other:
        return []
    ids = lambda model: {str(c.get("id")): ET.tostring(c, encoding="unicode") for c in ET.fromstring(model).iter("mxCell")}
    old, new = ids(one), ids(other)
    return sorted(i for i in old.keys() | new.keys() if old.get(i) != new.get(i))


def committed(folder):
    """The pair as committed at git HEAD: the source's text (the file, or the article's block) and the model embedded in the png, read
    with `git show`. None when the diagram is outside a repository or either side is not committed: an untracked pair has no base."""
    stem = diagram_of(folder).resolve()
    run = lambda *args: subprocess.run(["git", "-C", str(stem.parent), *args], capture_output=True)
    top = run("rev-parse", "--show-toplevel")
    if top.returncode != 0:
        return None
    root = Path(top.stdout.decode("utf-8").strip()).resolve()
    rel = stem.relative_to(root).as_posix()
    png = run("show", f"HEAD:{rel}{SLIDE}")
    if png.returncode != 0:
        return None
    if carrier_of(stem) == "file":
        source = run("show", f"HEAD:{rel}{SOURCE}")
        if source.returncode != 0:
            return None
        text = source.stdout.decode("utf-8")
    else:
        # The committed block is the one the committed article page holds; a page that is not committed, or holds none or two, has no base.
        page = article_block(stem)[0]
        shown = run("show", f"HEAD:{page.resolve().relative_to(root).as_posix()}")
        if shown.returncode != 0:
            return None
        whole = shown.stdout.decode("utf-8")
        spans = blocks_in(whole, stem.name)
        if len(spans) != 1:
            return None
        text = whole[spans[0][0] : spans[0][1]]
    return text, decode(mxfile_chunk(Image.open(io.BytesIO(png.stdout)))).strip()


def kind_of(folder):
    """The diagram kind its path names (explanation or reference), or None."""
    return next((k for k in KINDS if f"/{k}/" in Path(folder).resolve().as_posix()), None)


def conflict(folder, base):
    """The cells of a pair whose two sides both moved from the committed pair and now disagree: the yml differs from the base's,
    the png's model differs from the base's, and get of the png states other content than the yml. Empty when only one side moved,
    when the sides agree, or when there is no base (base None: an untracked pair is never a conflict). A conflicted pair is put or
    got only by name, so the author picks the side that wins; nothing merges."""
    if base is None:
        return []
    # The base is compared as data, never validated: it was valid against the registries of its own commit, not today's.
    source, model = load(folder), model_of(folder)
    unmoved = yaml.safe_load(read_source(folder)[0]) == yaml.safe_load(base[0])
    if unmoved or model == base[1]:
        return []
    back = undrawn(get(model, kind_of(folder))["content"], source)
    if drawn(back) == drawn(source["content"]):
        return []
    # The cells that diverge are drawn ones: a derived cell (a minimap, the legend) is stale at worst, never a side to pick.
    return [
        i for i in changed_cells(model, put(with_data(folder, source)).strip()) if i not in DERIVED and not i.startswith(DERIVED_PREFIXES)
    ]


def sync(folder, base):
    """The sync after an edit: get when the drawing moved from the base (or there is no base), then put, so the yml and the png
    agree again; put alone when only the yml moved. The directions run, in order. A conflicted pair runs nothing and fails with
    its cells, so the author picks the side by name."""
    both = conflict(folder, base)
    if both:
        raise DeclarationError(
            f"{folder}: the yml and the png both moved from HEAD and disagree in {', '.join(both)}; put or get it by name"
        )
    ran = []
    if base is None or model_of(folder) != base[1]:
        save(folder, get(model_of(folder), kind_of(folder)))
        ran.append("get")
    put_png(folder, load(folder))
    return ran + ["put"]


def main():
    args = sys.argv[1:]
    if len(args) >= 2 and args[0] == "check":  # one JSON line per diagram: conflicted or drifted cells, stale minimaps, or the error
        import drawio_forward

        for name in args[1:]:
            folder = diagram_of(name)
            try:
                # A legend diagram has no source: its png is checked against the painted glyph library, stale when a kit change moved it.
                if drawio_forward.diagram_role(folder) == "legend":
                    stale = ["legend"] if drawio_forward.legend_stale(folder) else []
                    print(json.dumps({"diagram": name, "conflict": [], "drift": [], "stale": stale}))
                    continue
                # A diagram declared in both carriers is a finding before anything is compared.
                twice = carrier_findings(folder)
                if twice:
                    print(json.dumps({"diagram": name, "error": "; ".join(twice)}))
                    continue
                both = conflict(folder, committed(folder))
                cells, stale = ([], []) if both else drift(folder)
                print(json.dumps({"diagram": name, "conflict": both, "drift": cells, "stale": stale}))
            except (DeclarationError, OSError, ValueError) as error:
                print(json.dumps({"diagram": name, "error": str(error)}))
        return
    if len(args) == 2 and args[0] == "tidy":  # the source re-saved through the kit: normalised, the retired about keys dropped
        folder = diagram_of(args[1])
        save(folder, load(folder))
        print(f"tidy {read_source(folder)[1]}")
        return
    if len(args) == 2 and args[0] == "reflow":  # the source rewritten in the printed form, its head and rows kept, its load() unchanged
        print(f"reflow {reflow(diagram_of(args[1]))}")
        return
    if len(args) == 3 and args[0] == "carry":  # the declaration moved to the other carrier, drawio.yml carriers: recording it
        where, png = carry(diagram_of(args[1]), args[2])
        target = png.resolve().relative_to(KIT.parents[1]).as_posix() if png.resolve().is_relative_to(KIT.parents[1]) else png
        print(f"carry {where}; render with: Build-Diagrams -Path {target}")
        return
    if (
        len(args) in (3, 4) and args[0] == "rekey"
    ):  # a moved stem's carriers: and roles: entries re-keyed, in the kit's drawio.yml or the given one
        config = Path(args[3]) if len(args) == 4 else CONFIG
        before = config.read_text(encoding="utf-8")
        after = rekeyed(before, args[1], args[2])
        if after != before:
            config.write_text(after, encoding="utf-8", newline="\n")
        print(f"rekey {config}: {'re-keyed' if after != before else 'unchanged'}")
        return
    if len(args) == 2 and args[0] == "minimaps":  # the diagram's minimap inputs rewritten in the printed form
        print(f"minimaps {declare_minimaps(diagram_of(args[1]))}")
        return
    if len(args) == 2 and args[0] == "sync":  # one JSON line: the directions run, or the conflict that stopped them
        folder = diagram_of(args[1])
        try:
            print(json.dumps({"diagram": args[1], "ran": sync(folder, committed(folder))}))
        except DeclarationError as error:
            print(json.dumps({"diagram": args[1], "error": str(error)}))
        return
    if len(args) < 2 or args[0] not in ("put", "get"):
        raise SystemExit(__doc__)
    direction, folder = args[0], diagram_of(args[1])
    if direction == "put":
        declaration = load(folder)
        if "--xml" in args:
            Path(args[args.index("--xml") + 1]).write_text(put(declaration), encoding="utf-8")
        dst = put_png(folder, declaration)
        print(f"put {dst}")
    else:
        save(folder, get(model_of(folder), kind_of(folder)))
        print(f"get {read_source(folder)[1]}")


if __name__ == "__main__":
    main()
